                            ExpressionType = "BinOp",
                            Value = new { op = "//", left = result, right = right }
                        };
                        continue;
                    }
                    Reset(mark);
                }

                if (CurrentToken?.Type.ToString() == "OP" && CurrentToken?.Value == "%")
                {
                    Advance(); // consume '%'
                    var right = ParseFactor();
                    if (right != null)
                    {
                        result = new GeneratedExpr
                        {
                            ExpressionType = "BinOp",
                            Value = new { op = "%", left = result, right = right }
                        };
                        continue;
                    }
                    Reset(mark);
                }

                if (CurrentToken?.Type.ToString() == "OP" && CurrentToken?.Value == "@")
                {
                    Advance(); // consume '@'
                    var right = ParseFactor();
                    if (right != null)
                    {
                        result = new GeneratedExpr
                        {
                            ExpressionType = "BinOp",
                            Value = new { op = "@", left = result, right = right }
                        };
                        continue;
                    }
                    Reset(mark);
                }

                // No more operations
                break;
            }

            return result;
        }

        // sum: sum '+' term | sum '-' term | term
        protected GeneratedExpr? ParseSum()
        {

            // Check for tokens that should stop parsing
            if (CurrentToken == null) return null;
            if (CurrentToken.Type == GeneratedTokenType.DEDENT) return null;
            if (CurrentToken.Type == GeneratedTokenType.ENDMARKER) return null;

            var result = ParseTerm();
            if (result == null) return null;

            // Handle left recursion iteratively
            while (true)
            {
                var mark = Mark();

                if (CurrentToken?.Type.ToString() == "OP" && CurrentToken?.Value == "+")
                {
                    Advance(); // consume '+'
                    var right = ParseTerm();
                    if (right != null)
                    {
                        result = new GeneratedExpr
                        {
                            ExpressionType = "BinOp",
                            Value = new { op = "+", left = result, right = right }
                        };
                        continue;
                    }
                    Reset(mark);
                }

                if (CurrentToken?.Type.ToString() == "OP" && CurrentToken?.Value == "-")
                {
                    Advance(); // consume '-'
                    var right = ParseTerm();
                    if (right != null)
                    {
                        result = new GeneratedExpr
                        {
                            ExpressionType = "BinOp",
                            Value = new { op = "-", left = result, right = right }
                        };
                        continue;
                    }
                    Reset(mark);
                }

                // No more operations
                break;
            }

            return result;
        }

