        // Rule: if_stmt from python.gram
        public GeneratedStmt IfStmt()
        {
            // CPython 3.12 PEG: if_stmt
            int _mark = _position;
            GeneratedStmt _res = null;

            // Alternative 1
            {
                _position = _mark;

                // Call rule: invalid_if_stmt
                var _tmp0 = InvalidIfStmt();
                if (_tmp0 == null)
                {
                    _position = _mark;
                    _res = null;
                    goto alternative_failed;
                }
                // No action specified - using default result
                _res = default(GeneratedStmt);
                if (_res != null) goto done;
            }

            alternative_failed:
            ;
            // Alternative 2
            {
                _position = _mark;

                // Expect 'if'
                if (!Expect("if"))
                {
                    _position = _mark;
                    _res = null;
                    goto alternative_failed;
                }
                // Call rule: named_expression
                var a = NamedExpression();
                if (a == null)
                {
                    _position = _mark;
                    _res = null;
                    goto alternative_failed;
                }
                // Expect ':'
                if (!Expect(":"))
                {
                    _position = _mark;
                    _res = null;
                    goto alternative_failed;
                }
                // Call rule: block
                var b = Block();
                if (b == null)
                {
                    _position = _mark;
                    _res = null;
                    goto alternative_failed;
                }
                // Call rule: elif_stmt
                var c = ElifStmt();
                if (c == null)
                {
                    _position = _mark;
                    _res = null;
                    goto alternative_failed;
                }
                // Action: _PyAST_If(a, b, CHECK(asdl_stmt_seq*, _PyPegen_singleton_seq(p, c)), EXTRA)
                _res = _PyAST_If(a, b, c);

                if (_res != null) goto done;
            }

            // Alternative 3
            {
                _position = _mark;

                // Expect 'if'
                if (!Expect("if"))
                {
                    _position = _mark;
                    _res = null;
                    goto alternative_failed;
                }
                // Call rule: named_expression
                var a = NamedExpression();
                if (a == null)
