        public GeneratedExpr? Conjunction()
        {
            // Try to parse: a=inversion b=('and' c=inversion { c })+
            var left = Inversion();
            if (left == null) return null;

            var andExpressions = new List<object>();
            andExpressions.Add(left);

            // Look for 'and' followed by inversion
            while (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "and")
            {
                Advance(); // consume 'and'
                var right = Inversion();
                if (right == null)
                {
                    // Error: expected inversion after 'and'
                    return null;
                }
                andExpressions.Add(right);
            }

            // If we found 'and' expressions, create BoolOp
            if (andExpressions.Count > 1)
            {
                return new GeneratedExpr
                {
                    ExpressionType = "BoolOp",
                    Value = new { op = "And", values = andExpressions }
                };
            }

            // Single inversion - return it
            return left;
        }

        /// <summary>
        /// inversion[expr_ty] (memo): | 'not' a=inversion | comparison
        /// Handles 'not' unary operations
        /// </summary>
        public GeneratedExpr? Inversion()
        {
            // Try to parse: 'not' a=inversion
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "not")
            {
                Advance(); // consume 'not'
                var operand = Inversion(); // recursive call for 'not not x'
                if (operand == null)
                {
                    // Error: expected expression after 'not'
                    return null;
                }

                return new GeneratedExpr
                {
                    ExpressionType = "UnaryOp",
                    Value = new { op = "Not", operand = operand }
                };
            }

            // Fall back to comparison - wrap result in GeneratedExpr
            var result = Comparison();
            if (result != null)
            {
                return new GeneratedExpr
                {
                    ExpressionType = "Expression",
                    Value = result
                };
            }
            return null;
        }

        /// <summary>
        /// comparison[expr_ty]: bitwise_or (('==' | '!=' | '<=' | '>=' | '<' | '>' | 'in' | 'not' 'in' | 'is' | 'is' 'not') bitwise_or)*
        /// Handles comparison operations
        /// </summary>
        public GeneratedExpr? Comparison()
        {
            var left = ParseSum(); // Start with sum for arithmetic precedence
            if (left == null) return null;

            var comparisons = new List<object>();
            var operators = new List<string>();

            // Look for comparison operators
            while (CurrentToken != null)
            {
                string? op = null;

                if (CurrentToken.Type == GeneratedTokenType.OP)
                {
                    switch (CurrentToken.Value)
                    {
                        case "==": op = "Eq"; Advance(); goto operator_found;
                        case "!=": op = "NotEq"; Advance(); goto operator_found;
                        case "<": op = "Lt"; Advance(); goto operator_found;
                        case "<=": op = "LtE"; Advance(); goto operator_found;
                        case ">": op = "Gt"; Advance(); goto operator_found;
                        case ">=": op = "GtE"; Advance(); goto operator_found;
                    }
                }
                else if (CurrentToken.Type == GeneratedTokenType.NAME)
                {
                    // CPython 3.12: Handle 'not in' and 'is not' as 2-token sequences
                    if (CurrentToken.Value == "not")
                    {
                        var nextPos = _position + 1;
                        if (nextPos < _tokens.Count && _tokens[nextPos].Type == GeneratedTokenType.NAME)
                        {
                            if (_tokens[nextPos].Value == "in")
                            {
                                op = "NotIn";
                                Advance(); // consume 'not'
                                Advance(); // consume 'in'
                                goto operator_found;
                            }
                        }
                    }
                    else if (CurrentToken.Value == "is")
                    {
                        var nextPos = _position + 1;
                        if (nextPos < _tokens.Count && _tokens[nextPos].Type == GeneratedTokenType.NAME && _tokens[nextPos].Value == "not")
                        {
                            op = "IsNot";
                            Advance(); // consume 'is'
                            Advance(); // consume 'not'
                            goto operator_found;
                        }
                        else
                        {
                            op = "Is";
                            Advance(); // consume 'is'
                            goto operator_found;
                        }
                    }
                    else if (CurrentToken.Value == "in")
                    {
                        op = "In";
                        Advance(); // consume 'in'
                        goto operator_found;
                    }
                }

                operator_found:

                if (op == null) break; // No more comparison operators

                // Note: operator already consumed by specific handlers above
                var right = ParseSum();
                if (right == null)
                {
                    // Error: expected expression after comparison operator
                    return null;
                }

                comparisons.Add(right);
                operators.Add(op);
            }

            // If we found comparison operators, create Compare expression
            if (comparisons.Count > 0)
            {
                return new GeneratedExpr
                {
                    ExpressionType = "Compare",
                    Value = new { left = left, ops = operators, comparators = comparisons }
                };
            }

            // No comparison operators - return left operand wrapped in GeneratedExpr
            if (left is GeneratedExpr genExpr)
            {
                return genExpr;
            }

            return new GeneratedExpr
            {
                ExpressionType = "Expression",
                Value = left
            };
        }


