        /// <summary>
        /// compound_stmt[stmt_ty]: CPython 3.12 grammar-based parsing
        /// compound_stmt[stmt_ty]:
        ///     | &('def' | '@' | ASYNC) function_def
        ///     | &'if' if_stmt
        ///     | &('class' | '@') class_def
        ///     | &('with' | ASYNC) with_stmt
        ///     | &('for' | ASYNC) for_stmt
        ///     | &'try' try_stmt
        ///     | &'while' while_stmt
        ///     | match_stmt
        /// </summary>
        public GeneratedStmt ParseCompoundStmt()
        {
            Console.WriteLine($"[DEBUG] ParseCompoundStmt: pos={_position}, token={CurrentToken?.Type}:{CurrentToken?.Value}");

            // CPython 3.12: Use PegInterpreter for grammar-based parsing
            // Try to parse compound_stmt using the grammar
            var startPos = _position;

            // Check for decorator (function or class definition with decorators)
            if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken.Value == "@")
            {
                var decorators = ParseDecorators();
                if (decorators != null)
                {
                    // Check what follows the decorators
                    if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "def")
                    {
                        var function = ParseFunctionDefRaw();
                        if (function != null)
                        {
                            function.Decorators = decorators;
                            return function;
                        }
                    }
                    else if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "class")
                    {
                        var cls = ParseClassDefRaw();
                        if (cls != null)
                        {
                            cls.Decorators = decorators;
                            return cls;
                        }
                    }
                }
                return null; // Invalid decorator usage
            }

            // Check for async (function or for/with)
            if (CurrentToken?.Type == GeneratedTokenType.ASYNC)
            {
                Console.WriteLine($"[DEBUG] ParseCompoundStmt: Found ASYNC token");
                return ParseFunctionDef();
            }

            // Check for function definition
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "def")
            {
                return ParseFunctionDef();
            }

            // Check for class statement
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "class")
            {
                Console.WriteLine($"[DEBUG] ParseCompoundStmt: Found class statement");
                var result = ParseClassDef() as GeneratedStmt;
                return result;
            }

            // Check for match statement (Python 3.10+)
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "match")
            {
                Console.WriteLine($"[DEBUG] ParseCompoundStmt: Found match statement");
                var result = ParseMatchStatement() as GeneratedStmt;
                return result;
            }

            // Check for try statement
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "try")
            {
                Console.WriteLine($"[DEBUG] ParseCompoundStmt: Found try statement");
                var result = ParseTryStatement() as GeneratedStmt;
                return result;
            }

            // Check for with statement
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "with")
            {
                Console.WriteLine($"[DEBUG] ParseCompoundStmt: Found with statement");
                var result = ParseWithStatement() as GeneratedStmt;
                return result;
            }

            // CPython 3.12: if/while/for statements use grammar-generated methods
            // These methods are auto-generated from python.gram
            Console.WriteLine($"[DEBUG] ParseCompoundStmt: Checking if/while/for");

            // Check for if statement
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "if")
            {
                Console.WriteLine($"[DEBUG] ParseCompoundStmt: Found if, calling IfStmt");
                var result = IfStmt();
                if (result != null)
                {
                    Console.WriteLine($"[DEBUG] ParseCompoundStmt: IfStmt succeeded");
                    return result;
                }
            }

            // Check for while statement
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "while")
            {
                Console.WriteLine($"[DEBUG] ParseCompoundStmt: Found while, calling WhileStmt");
                var result = WhileStmt();
                if (result != null)
                {
                    Console.WriteLine($"[DEBUG] ParseCompoundStmt: WhileStmt succeeded");
                    return result;
                }
            }

            // Check for for statement
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "for")
            {
                Console.WriteLine($"[DEBUG] ParseCompoundStmt: Found for, calling ForStmt");
                var result = ForStmt();
                if (result != null)
                {
                    Console.WriteLine($"[DEBUG] ParseCompoundStmt: ForStmt succeeded");
                    return result;
                }
            }

            Console.WriteLine($"[DEBUG] ParseCompoundStmt: No compound statement matched");
            return null;
        }

        /// <summary>
        /// function_def[stmt_ty]: decorators function_def_raw | function_def_raw
        /// </summary>
        public GeneratedStmt ParseFunctionDef()
        {
            // For now, just handle function_def_raw (no decorators)
            return ParseFunctionDefRaw();
        }

        /// <summary>
        /// function_def_raw[stmt_ty]: 'def' n=NAME '(' params=[params] ')' ':' b=block
        ///                        | ASYNC 'def' n=NAME '(' params=[params] ')' ':' b=block
        /// { _PyAST_FunctionDef / _PyAST_AsyncFunctionDef }
        /// </summary>
        public GeneratedStmt ParseFunctionDefRaw()
        {
            Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: Starting at position {_position}, token: {CurrentToken?.Type} '{CurrentToken?.Value}'");

            var startPos = _position;
            bool isAsync = false;

            // Check for ASYNC 'def' or just 'def'
            if (CurrentToken?.Type == GeneratedTokenType.ASYNC)
            {
                isAsync = true;
                Advance(); // consume ASYNC
                Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: Found ASYNC keyword, expecting 'def' next");
            }

            // 'def'
            if (!ExpectKeyword("def"))
            {
                Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: Failed to match 'def' keyword at position {_position}");
                _position = startPos;
                return null;
            }

            // NAME
            var name = ExpectName();
            if (name == null)
            {
                Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: Failed to match function name at position {_position}");
                _position = startPos;
                return null;
            }

            // [type_params] - Optional type parameters for PEP 695
            var typeParams = ParseTypeParams();

            // '('
            if (!ExpectToken(GeneratedTokenType.OP, "("))
            {
                Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: Failed to match '(' at position {_position}");
                _position = startPos;
                return null;
            }

            // [params] - Parse function parameters
            Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: About to parse parameters at position {_position}");
            var parameters = ParseParams();
            Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: Parameters parsing completed");

            // ')'
            if (!ExpectToken(GeneratedTokenType.OP, ")"))
            {
                Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: Failed to match ')' at position {_position}");
                _position = startPos;
                return null;
            }

            // ['->' expression] - Optional return type annotation
            object returnAnnotation = null;
            if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == "->")
            {
                Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: Found '->' for return type annotation at position {_position}");
                Advance(); // consume '->'
                returnAnnotation = ParseExpression();
                if (returnAnnotation != null)
                {
                    Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: parsed return type annotation");
                }
                else
                {
                    Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: failed to parse return type annotation");
                    _position = startPos;
                    return null;
                }
            }

            // ':'
            if (!ExpectToken(GeneratedTokenType.OP, ":"))
            {
                Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: Failed to match ':' at position {_position}");
                _position = startPos;
                return null;
            }

            // block
            var body = ParseBlock();
            if (body == null)
            {
                Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: Failed to parse function body at position {_position}");
                _position = startPos;
                return null;
            }

            // Return the appropriate result based on async/sync
            if (isAsync)
            {
                Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: Successfully parsed async function '{name}' at position {_position}");
                return _PyAST_AsyncFunctionDef(name, parameters, body, type_params: typeParams);
            }
            else
            {
                Console.WriteLine($"[DEBUG] ParseFunctionDefRaw: Successfully parsed function '{name}' at position {_position}");
                return _PyAST_FunctionDef(name, parameters, body, type_params: typeParams);
            }
        }

        /// <summary>
        /// statements[asdl_stmt_seq*]: a=statement+ { (asdl_stmt_seq*)_PyPegen_seq_flatten(p, a) }
        /// </summary>
        public List<object> ParseStatements()
        {
            var statements = new List<object>();
            int iterationCount = 0;
            while (_position < _tokens.Count && CurrentToken?.Type != GeneratedTokenType.ENDMARKER)
            {
                iterationCount++;
                Console.WriteLine($"[DEBUG] ParseStatements: Loop iteration " + iterationCount);

                // Skip NEWLINE, NL, COMMENT tokens at module level
                if (CurrentToken?.Type == GeneratedTokenType.NEWLINE || CurrentToken?.Type == GeneratedTokenType.NL || CurrentToken?.Type == GeneratedTokenType.COMMENT)
                {
                    Advance();
                    continue;
                }

                // CPython 3.12: At module level, DEDENT tokens complete indented blocks
                // We should continue parsing the next statement after DEDENT

                var startPos = _position; // Track starting position
                var stmt = ParseStatement();
                Console.WriteLine($"[DEBUG] ParseStatements: ParseStatement returned: " + (stmt != null ? "SUCCESS" : "NULL"));
                if (stmt != null)
                {
                    if (_position == startPos)
                    {
                        // CRITICAL: Position didn't advance - force advance to prevent infinite loop
                        Console.WriteLine($"[WARNING] ParseStatements: Position {_position} didn't advance, forcing advance to prevent infinite loop. Token: {CurrentToken?.Type} '{CurrentToken?.Value}'");
                        Advance();
                        continue;
                    }
                    if (stmt is List<object> stmtList)
                        statements.AddRange(stmtList);
                    else
                        statements.Add(stmt);
                }
                else
                {
                    break;
                }
            }
            Console.WriteLine($"[DEBUG] ParseStatements: Loop terminated. Position: " + _position + ", TokenCount: " + _tokens.Count + ", CurrentToken: " + (CurrentToken?.Type.ToString() ?? "null"));
            return _PyPegen_seq_flatten(statements);
        }

        /// <summary>
        /// Parse statements until we encounter a DEDENT that closes the current indentation level
        /// </summary>
        public List<object> ParseStatementsUntilDedent()
        {
            var statements = new List<object>();

            while (_position < _tokens.Count && CurrentToken?.Type != GeneratedTokenType.ENDMARKER)
            {
                // Skip NEWLINE, NL, COMMENT tokens
                if (CurrentToken?.Type == GeneratedTokenType.NEWLINE || CurrentToken?.Type == GeneratedTokenType.NL || CurrentToken?.Type == GeneratedTokenType.COMMENT)
                {
                    Advance();
                    continue;
                }

                // CPython 3.12: DEDENT token marks the end of current indentation level
                // block: NEWLINE INDENT statements DEDENT - DEDENT closes the block immediately
                if (CurrentToken?.Type == GeneratedTokenType.DEDENT)
                {
                    Advance(); // consume DEDENT
                    Console.WriteLine($"[DEBUG] ParseStatementsUntilDedent: Found DEDENT, block parsing complete with {statements.Count} statements");
                    return statements;
                }

                var startPos = _position;
                var stmt = ParseStatement();
                if (stmt != null)
                {
                    if (_position == startPos)
                    {
                        Console.WriteLine($"[WARNING] ParseStatementsUntilDedent: Position didn't advance, breaking to prevent infinite loop");
                        break;
                    }
                    if (stmt is List<object> stmtList)
                        statements.AddRange(stmtList);
                    else
                        statements.Add(stmt);
                }
                else
                {
                    break;
                }
            }

            Console.WriteLine($"[DEBUG] ParseStatementsUntilDedent: Finished parsing, returning {statements.Count} statements");
            return statements;
        }

        /// <summary>
        /// statement[asdl_stmt_seq*]: a=compound_stmt { (asdl_stmt_seq*)_PyPegen_singleton_seq(p, a) } | a[asdl_stmt_seq*]=simple_stmts { a }
        /// </summary>
        public object ParseStatement()
        {
            var startPos = _position; // Track starting position to prevent infinite loops
            Console.WriteLine($"[DEBUG] ParseStatement: Starting at position {_position}, token: {CurrentToken?.Type} '{CurrentToken?.Value}'");

            // Try compound statement first
            var compound = ParseCompoundStmt();
            if (compound != null)
            {
                if (_position == startPos)
                {
                    // CRITICAL: Position didn't advance - this indicates an infinite loop
                    Console.WriteLine($"[ERROR] ParseStatement: Position {_position} didn't advance after ParseCompoundStmt, forcing advance to prevent infinite loop. Token: {CurrentToken?.Type} '{CurrentToken?.Value}'");
                    Advance();
                    return null;
                }
                Console.WriteLine($"[DEBUG] ParseStatement: Found compound statement");
                return _PyPegen_singleton_seq(compound);
            }

            // Handle unexpected INDENT tokens at module level
            // INDENT tokens should not appear at module level - they indicate tokenizer/parser sync issues
            while (CurrentToken?.Type == GeneratedTokenType.INDENT)
            {
                Console.WriteLine($"[DEBUG] ParseStatement: Skipping unexpected INDENT token at module level: position {_position}");
                Advance();
            }

            // Try simple statements
            var simple = ParseSimpleStmts();
            if (simple != null)
            {
                if (_position == startPos)
                {
                    // CRITICAL: Position didn't advance - this indicates an infinite loop
                    Console.WriteLine($"[ERROR] ParseStatement: Position {_position} didn't advance after ParseSimpleStmts, forcing advance to prevent infinite loop. Token: {CurrentToken?.Type} '{CurrentToken?.Value}'");
                    Advance();
                    return null;
                }
                Console.WriteLine($"[DEBUG] ParseStatement: Found simple statements");
                return simple;
            }

            Console.WriteLine($"[DEBUG] ParseStatement: No statement found at position {_position}");
            return null;
        }

        /// <summary>
        /// simple_stmts[asdl_stmt_seq*]: simple_stmt (';' simple_stmt)* [';'] NEWLINE
        /// </summary>
        public List<object> ParseSimpleStmts()
        {
            var statements = new List<object>();
            var stmt = ParseSimpleStmt();
            if (stmt != null)
                statements.Add(stmt);

            // Handle semicolons and additional statements
            while (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken.Value == ";")
            {
                Advance(); // consume ';'

                // Optional trailing semicolon before NEWLINE
                if (CurrentToken?.Type == GeneratedTokenType.NEWLINE)
                    break;

                var nextStmt = ParseSimpleStmt();
                if (nextStmt != null)
                    statements.Add(nextStmt);
                else
                    break;
            }

            // Only expect NEWLINE if we're not at end of input and current token is NEWLINE
            if (CurrentToken?.Type == GeneratedTokenType.NEWLINE)
            {
                Advance(); // consume NEWLINE
            }

            return statements;
        }

        /// <summary>
        /// simple_stmt[stmt_ty]: CPython 3.12 order - assignment | star_expressions | 'pass' | 'return' | ...
        /// </summary>
        public GeneratedStmt ParseSimpleStmt()
        {
            // CPython 3.12: assignment FIRST
            var assignment = ParseAssignment();
            if (assignment != null)
            {
                return assignment;
            }

            // CPython 3.12: star_expressions (expression statement) SECOND
            // CRITICAL: Do not parse compound statement keywords as expressions
            if (CurrentToken?.Type == GeneratedTokenType.NAME)
            {
                var tokenValue = CurrentToken.Value;
                // Reject compound statement keywords and simple statement keywords
                if (tokenValue == "if" || tokenValue == "while" || tokenValue == "for" ||
                    tokenValue == "def" || tokenValue == "class" || tokenValue == "try" ||
                    tokenValue == "with" || tokenValue == "async" || tokenValue == "match" ||
                    tokenValue == "return" || tokenValue == "import" || tokenValue == "from" ||
                    tokenValue == "raise" || tokenValue == "pass" || tokenValue == "break" ||
                    tokenValue == "continue" || tokenValue == "global" || tokenValue == "nonlocal" ||
                    tokenValue == "del" || tokenValue == "yield" || tokenValue == "assert")
                {
                    // These are handled by their specific parsers below
                }
                else
                {
                    // Try expression statement
                    var expr = ParseExpression();
                    if (expr != null)
                        return _PyAST_Expr(expr);
                }
            }
            else
            {
                // Not a NAME token, try expression
                var expr = ParseExpression();
                if (expr != null)
                    return _PyAST_Expr(expr);
            }

            // CPython 3.12: &'return' return_stmt
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "return")
            {
                return ParseReturnStmt();
            }

            // CPython 3.12: &('import' | 'from') import_stmt
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "import")
            {
                return ParseImportStatement();
            }

            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "from")
            {
                return ParseFromImportStatement();
            }

            // CPython 3.12: &'raise' raise_stmt
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "raise")
            {
                return ParseRaiseStatement();
            }

            // CPython 3.12: 'pass'
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "pass")
            {
                Advance();
                return _PyAST_Pass();
            }

            // CPython 3.12: 'break'
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "break")
            {
                Advance();
                var breakStmt = new GeneratedStmt();
                breakStmt.StatementType = "break";
                return breakStmt;
            }

            // CPython 3.12: 'continue'
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken.Value == "continue")
            {
                Advance();
                var continueStmt = new GeneratedStmt();
                continueStmt.StatementType = "continue";
                return continueStmt;
            }


            return null;
        }

        /// <summary>
        /// return_stmt[stmt_ty]: 'return' a=[star_expressions] { _PyAST_Return(a, EXTRA) }
        /// </summary>
        public GeneratedStmt ParseReturnStmt()
        {
            if (!ExpectKeyword("return"))
                return null;

            // Optional return value
            var value = ParseExpression(); // Simplified - should be star_expressions
            return _PyAST_Return(value);
        }

        /// <summary>
        /// params[arguments_ty]: parameters
        /// </summary>
        public object ParseParams()
        {
            Console.WriteLine($"[DEBUG] ParseParams called at position {_position}");
            var result = ParseParameters();
            if (result != null)
            {
                Console.WriteLine($"[DEBUG] ParseParams: parameters rule succeeded");
                return result;
            }

            Console.WriteLine($"[DEBUG] ParseParams: parameters rule failed, returning empty arguments");
            return _PyPegen_empty_arguments();
        }

        /// <summary>
        /// parameters[arguments_ty]: CPython 3.12 compatible parameter parsing
        /// Implements: slash_no_default | slash_with_default | param_no_default+ | param_with_default+ | star_etc
        /// </summary>
        public object ParseParameters()
        {
            Console.WriteLine($"[DEBUG] ParseParameters called at position {_position}");

            var startPos = _position;

            // Try each alternative in order (PEG first-match semantics)

            // Alternative 1: a=slash_no_default b=param_no_default* c=param_with_default* d=[star_etc]
            var slashNoDefault = ParseSlashNoDefault();
            if (slashNoDefault != null)
            {
                var paramNoDefaults = new List<object>();
                while (true)
                {
                    var param = ParseParamNoDefault();
                    if (param == null) break;
                    paramNoDefaults.Add(param);
                }

                var paramWithDefaults = new List<object>();
                while (true)
                {
                    var param = ParseParamWithDefault();
                    if (param == null) break;
                    paramWithDefaults.Add(param);
                }

                var starEtc = ParseStarEtc();

                Console.WriteLine($"[DEBUG] ParseParameters: Alternative 1 matched - positional-only args: {((List<object>)slashNoDefault).Count}");
                return _PyPegen_make_arguments(this, slashNoDefault, null, paramNoDefaults, paramWithDefaults.Count > 0 ? paramWithDefaults : null, starEtc);
            }

            // Reset position for next alternative
            _position = startPos;

            // Alternative 2: a=slash_with_default b=param_with_default* c=[star_etc]
            var slashWithDefault = ParseSlashWithDefault();
            if (slashWithDefault != null)
            {
                var paramWithDefaults = new List<object>();
                while (true)
                {
                    var param = ParseParamWithDefault();
                    if (param == null) break;
                    paramWithDefaults.Add(param);
                }

                var starEtc = ParseStarEtc();

                Console.WriteLine($"[DEBUG] ParseParameters: Alternative 2 matched - positional-only args with defaults");
                return _PyPegen_make_arguments(this, null, slashWithDefault, null, paramWithDefaults.Count > 0 ? paramWithDefaults : null, starEtc);
            }

            // Reset position for next alternative
            _position = startPos;

            // Alternative 3: a=param_no_default+ b=param_with_default* c=[star_etc]
            var paramNoDefaults3 = new List<object>();
            var param3 = ParseParamNoDefault();
            if (param3 != null)
            {
                paramNoDefaults3.Add(param3);
                while (true)
                {
                    param3 = ParseParamNoDefault();
                    if (param3 == null) break;
                    paramNoDefaults3.Add(param3);
                }

                var paramWithDefaults3 = new List<object>();
                while (true)
                {
                    param3 = ParseParamWithDefault();
                    if (param3 == null) break;
                    paramWithDefaults3.Add(param3);
                }

                var starEtc3 = ParseStarEtc();

                Console.WriteLine($"[DEBUG] ParseParameters: Alternative 3 matched - regular args: {paramNoDefaults3.Count}");
                return _PyPegen_make_arguments(this, null, null, paramNoDefaults3, paramWithDefaults3.Count > 0 ? paramWithDefaults3 : null, starEtc3);
            }

            // Reset position for next alternative
            _position = startPos;

            // Alternative 4: a=param_with_default+ b=[star_etc]
            var paramWithDefaults4 = new List<object>();
            var param4 = ParseParamWithDefault();
            if (param4 != null)
            {
                paramWithDefaults4.Add(param4);
                while (true)
                {
                    param4 = ParseParamWithDefault();
                    if (param4 == null) break;
                    paramWithDefaults4.Add(param4);
                }

                var starEtc4 = ParseStarEtc();

                Console.WriteLine($"[DEBUG] ParseParameters: Alternative 4 matched - args with defaults: {paramWithDefaults4.Count}");
                return _PyPegen_make_arguments(this, null, null, null, paramWithDefaults4, starEtc4);
            }

            // Reset position for next alternative
            _position = startPos;

            // Alternative 5: a=star_etc
            var starEtc2 = ParseStarEtc();
            if (starEtc2 != null)
            {
                Console.WriteLine($"[DEBUG] ParseParameters: Alternative 5 matched - star_etc only");
                return _PyPegen_make_arguments(this, null, null, null, null, starEtc2);
            }

            Console.WriteLine($"[DEBUG] ParseParameters: no parameters found");
            return null;
        }
        /// <summary>
        /// slash_no_default[asdl_arg_seq*]: param_no_default+ '/' ','
        /// </summary>
        public object ParseSlashNoDefault()
        {
            var startPos = _position;
            var paramsList = new List<object>();

            // Parse param_no_default+
            var param = ParseParamNoDefault();
            if (param == null) return null;
            paramsList.Add(param);

            while (true)
            {
                param = ParseParamNoDefault();
                if (param == null) break;
                paramsList.Add(param);
            }

            // Expect '/'
            if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken.Value == "/")
            {
                Advance(); // consume '/'
                // Expect ',' or lookahead for ')'
                if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken.Value == ",")
                {
                    Advance(); // consume ','
                    Console.WriteLine($"[DEBUG] ParseSlashNoDefault: Found {paramsList.Count} positional-only parameters");
                    return paramsList;
                }
                else if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken.Value == ")")
                {
                    // Lookahead for ')' - don't consume
                    Console.WriteLine($"[DEBUG] ParseSlashNoDefault: Found {paramsList.Count} positional-only parameters (end)");
                    return paramsList;
                }
            }

            _position = startPos;
            return null;
        }

        /// <summary>
        /// slash_with_default[SlashWithDefault*]: param_no_default* param_with_default+ '/' ','
        /// </summary>
        public object ParseSlashWithDefault()
        {
            var startPos = _position;
            var noDefaults = new List<object>();
            var withDefaults = new List<object>();

            // Parse param_no_default*
            while (true)
            {
                var param = ParseParamNoDefault();
                if (param == null) break;
                noDefaults.Add(param);
            }

            // Parse param_with_default+
            var paramDefault = ParseParamWithDefault();
            if (paramDefault == null)
            {
                _position = startPos;
                return null;
            }
            withDefaults.Add(paramDefault);

            while (true)
            {
                paramDefault = ParseParamWithDefault();
                if (paramDefault == null) break;
                withDefaults.Add(paramDefault);
            }

            // Expect '/'
            if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken.Value == "/")
            {
                Advance();
                if (CurrentToken?.Type == GeneratedTokenType.OP && (CurrentToken.Value == "," || CurrentToken.Value == ")"))
                {
                    if (CurrentToken.Value == ",") Advance();
                    Console.WriteLine($"[DEBUG] ParseSlashWithDefault: Found positional-only with defaults");
                    return _PyPegen_slash_with_default(this, noDefaults, withDefaults);
                }
            }

            _position = startPos;
            return null;
        }

        /// <summary>
        /// param_no_default[arg_ty]: param ',' TYPE_COMMENT? | param TYPE_COMMENT? &(')'|'/')
        /// </summary>
        public object ParseParamNoDefault()
        {
            var startPos = _position;
            var param = ParseParam();
            if (param == null) return null;

            // Check for comma or lookahead for ')' or '/'
            if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken.Value == ",")
            {
                Advance(); // consume comma
                return param;
            }
            else if (CurrentToken?.Type == GeneratedTokenType.OP && (CurrentToken.Value == ")" || CurrentToken.Value == "/"))
            {
                // Lookahead - don't consume
                return param;
            }

            _position = startPos;
            return null;
        }

        /// <summary>
        /// param_with_default[NamedExpr]: param default ',' TYPE_COMMENT? | param default TYPE_COMMENT? &(')'|'/')
        /// </summary>
        public object ParseParamWithDefault()
        {
            var startPos = _position;
            var param = ParseParam();
            if (param == null) return null;

            // Expect '='
            if (CurrentToken?.Type != GeneratedTokenType.OP || CurrentToken.Value != "=")
            {
                _position = startPos;
                return null;
            }
            Advance(); // consume '='

            var defaultValue = ParseExpression();
            if (defaultValue == null)
            {
                _position = startPos;
                return null;
            }

            // Check for comma or lookahead
            if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken.Value == ",")
            {
                Advance(); // consume comma
            }
            else if (CurrentToken?.Type == GeneratedTokenType.OP && (CurrentToken.Value == ")" || CurrentToken.Value == "/"))
            {
                // Lookahead - don't consume
            }
            else
            {
                _position = startPos;
                return null;
            }

            return new { param = param, defaultValue = defaultValue };
        }

        /// <summary>
        /// param[arg_ty]: NAME annotation?
        /// </summary>
        public object ParseParam()
        {
            if (CurrentToken?.Type != GeneratedTokenType.NAME) return null;

            var name = CurrentToken.Value;
            Advance();

            object annotation = null;
            if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken.Value == ":")
            {
                Advance(); // consume ':'
                annotation = ParseExpression();
                if (annotation == null) return null;
            }

            return _PyAST_arg(name, annotation, null);
        }

        /// <summary>
        /// star_etc[StarEtc*]: '*' param_no_default param_maybe_default* [kwds] | '*' ',' param_maybe_default+ [kwds] | kwds
        /// </summary>
        /// <summary>
        /// star_etc[StarEtc*]: '*' a=param_no_default b=param_maybe_default* c=[kwds]
        ///                  | '*' ',' b=param_maybe_default+ c=[kwds]
        ///                  | a=kwds
        /// CPython 3.12: Must parse actual parameter name after * or **
        /// </summary>
        public object ParseStarEtc()
        {
            Console.WriteLine($"[DEBUG] ParseStarEtc: Starting at position {_position}, token: {CurrentToken?.Type} '{CurrentToken?.Value}'");
            var savedPos = _position;

            // Alternative 1: '*' param_no_default ...
            if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken.Value == "*")
            {
                Advance(); // consume '*'
                Console.WriteLine($"[DEBUG] ParseStarEtc: Consumed '*', now at: {CurrentToken?.Type} '{CurrentToken?.Value}'");
                
                var result = new Dictionary<string, object>();
                result["kwonlyargs"] = new List<object>();
                result["kwarg"] = null;
                
                // CPython 3.12: Parse NAME token for vararg parameter
                if (CurrentToken?.Type == GeneratedTokenType.NAME)
                {
                    var paramName = CurrentToken.Value;
                    Console.WriteLine($"[DEBUG] ParseStarEtc: Found vararg NAME: {paramName}");
                    Advance(); // consume NAME
                    result["vararg"] = paramName;
                }
                else if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken.Value == ",")
                {
                    // '*' ',' case - bare star for keyword-only args
                    Console.WriteLine($"[DEBUG] ParseStarEtc: Bare '*' (keyword-only marker)");
                    result["vararg"] = null;
                }
                else
                {
                    Console.WriteLine($"[ERROR] ParseStarEtc: Expected NAME or ',' after '*', got: {CurrentToken?.Type} '{CurrentToken?.Value}'");
                    _position = savedPos;
                    return null;
                }
                
                Console.WriteLine($"[DEBUG] ParseStarEtc: Successfully parsed '*' alternative");
                return result;
            }

            // Alternative 2: '**' param_no_default
            if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken.Value == "**")
            {
                Advance(); // consume '**'
                Console.WriteLine($"[DEBUG] ParseStarEtc: Consumed '**', now at: {CurrentToken?.Type} '{CurrentToken?.Value}'");
                
                // CPython 3.12: Parse NAME token for kwarg parameter
                if (CurrentToken?.Type == GeneratedTokenType.NAME)
                {
                    var paramName = CurrentToken.Value;
                    Console.WriteLine($"[DEBUG] ParseStarEtc: Found kwarg NAME: {paramName}");
                    Advance(); // consume NAME
                    
                    var result = new Dictionary<string, object>();
                    result["vararg"] = null;
                    result["kwonlyargs"] = new List<object>();
                    result["kwarg"] = paramName;
                    
                    Console.WriteLine($"[DEBUG] ParseStarEtc: Successfully parsed '**' alternative");
                    return result;
                }
                else
                {
                    Console.WriteLine($"[ERROR] ParseStarEtc: Expected NAME after '**', got: {CurrentToken?.Type} '{CurrentToken?.Value}'");
                    _position = savedPos;
                    return null;
                }
            }

            Console.WriteLine($"[DEBUG] ParseStarEtc: No match found");
            return null;
        }

        /// <summary>
        /// block[asdl_stmt_seq*]: NEWLINE INDENT statements DEDENT | simple_stmts
        /// </summary>
        public List<object> ParseBlock()
        {
            Console.WriteLine($"[DEBUG] ParseBlock: Starting at position {_position}, token: {CurrentToken?.Type} '{CurrentToken?.Value}'");

            // Use left-recursion handling for block parsing
            return TryLeftRecursive<List<object>>("ParseBlock", () =>
            {
                var statements = new List<object>();

            // CPython 3.12 block grammar: NEWLINE INDENT statements DEDENT | simple_stmts
            // First alternative: NEWLINE INDENT statements DEDENT
            if (CurrentToken?.Type == GeneratedTokenType.NEWLINE)
            {
                var savedPos = _position;
                Advance(); // consume NEWLINE

                if (CurrentToken?.Type == GeneratedTokenType.INDENT)
                {
                    Advance(); // consume INDENT

                    var blockStatements = ParseStatementsUntilDedent();
                    if (blockStatements != null)
                    {
                        Console.WriteLine($"[DEBUG] ParseBlock: Successfully parsed indented block with {blockStatements.Count} statements");
                        return blockStatements;
                    }
                }

                // Failed to parse indented block, restore position and try simple_stmts
                _position = savedPos;
            }

            // Second alternative: simple_stmts
            var stmt = ParseSimpleStmts();
            if (stmt != null)
            {
                if (stmt is List<object> stmtList)
                    return stmtList;
                else
                {
                    statements.Add(stmt);
                    return statements;
                }
            }

            Console.WriteLine($"[DEBUG] ParseBlock: Returning result with {statements.Count} statements at position {_position}");
            return statements;
            });
        }

        /// <summary>
        /// Parse class body without left-recursion
        /// </summary>
        public List<object> ParseClassBody()
        {
            Console.WriteLine($"[DEBUG] ParseClassBody: Starting at position {_position}, token: {CurrentToken?.Type} '{CurrentToken?.Value}'");
            var statements = new List<object>();

            // CPython 3.12: Track class body indentation level for accurate parsing
            int? classBodyIndentLevel = null;

            if (CurrentToken?.Type == GeneratedTokenType.NEWLINE)
            {
                Advance(); // consume NEWLINE
                
                // Record the class body indentation level before consuming INDENT token
                if (CurrentToken?.Type == GeneratedTokenType.INDENT && CurrentToken?.Value != null)
                {
                    classBodyIndentLevel = CurrentToken.Value.Length;
                    Console.WriteLine($"[DEBUG] ParseClassBody: Recorded class body indent level: {classBodyIndentLevel}");
                }
                
                if (!ExpectToken(GeneratedTokenType.INDENT))
                {
                    Console.WriteLine($"[DEBUG] ParseClassBody: Expected INDENT after class declaration");
                    return statements;
                }

                // Parse statements until class body ends
                // A class body ends when we see a final DEDENT at the class level
                while (CurrentToken != null)
                {
                    // Check for end of class body - DEDENT followed by non-INDENT token
                    if (CurrentToken.Type == GeneratedTokenType.DEDENT)
                    {
                        // CPython 3.12: Check if this DEDENT ends the class body
                        // Calculate current indentation level after DEDENT
                        int currentIndentLevel = 0;
                        int nextPos = _position + 1;
                        
                        // Look ahead to find the next significant token and its indentation
                        while (nextPos < _tokens.Count)
                        {
                            var nextToken = _tokens[nextPos];
                            if (nextToken.Type == GeneratedTokenType.NL)
                            {
                                nextPos++;
                                continue;
                            }
                            else if (nextToken.Type == GeneratedTokenType.INDENT)
                            {
                                // Get indentation level from INDENT token
                                if (nextToken.Value != null)
                                {
                                    currentIndentLevel = nextToken.Value.Length;
                                }
                                nextPos++;
                            }
                            else
                            {
                                // Found the next significant token
                                break;
                            }
                        }

                        bool hasMoreClassContent = false;
                        if (nextPos < _tokens.Count)
                        {
                            var nextToken = _tokens[nextPos];
                            // Check if we're still at class body level and have class-level statements
                            if (classBodyIndentLevel.HasValue && currentIndentLevel == classBodyIndentLevel.Value &&
                                nextToken.Type == GeneratedTokenType.NAME && 
                                (nextToken.Value == "def" || nextToken.Value == "class" || nextToken.Value == "async"))
                            {
                                hasMoreClassContent = true;
                            }
                            else if (classBodyIndentLevel.HasValue && currentIndentLevel == classBodyIndentLevel.Value &&
                                     nextToken.Type == GeneratedTokenType.OP && nextToken.Value == "@")
                            {
                                hasMoreClassContent = true;
                            }
                        }
                        if (hasMoreClassContent)
                        {
                            Console.WriteLine($"[DEBUG] ParseClassBody: Found DEDENT at indent level {currentIndentLevel}, same as class level {classBodyIndentLevel}, continuing class body");
                            Advance(); // Skip the DEDENT
                            continue;  // Continue parsing the next statement
                        }
                        else
                        {
                            Console.WriteLine($"[DEBUG] ParseClassBody: Found DEDENT at indent level {currentIndentLevel}, different from class level {classBodyIndentLevel}, ending class body");
                            break; // End of class body
                        }
                    }

                    // Skip blank lines (NL tokens) in class body
                    if (CurrentToken?.Type == GeneratedTokenType.NL)
                    {
                        Console.WriteLine($"[DEBUG] ParseClassBody: Skipping NL token at position {_position}");
                        Advance();
                        continue;
                    }

                    // Handle INDENT tokens within class body (for method definitions after blank lines)
                    if (CurrentToken?.Type == GeneratedTokenType.INDENT)
                    {
                        Console.WriteLine($"[DEBUG] ParseClassBody: Found INDENT token, checking if it matches class level");
                        // In a class body, INDENT tokens can appear before method definitions
                        // Skip the INDENT and continue parsing the method
                        Advance();
                        continue;
                    }

                    var stmt = ParseStatement();
                    if (stmt != null)
                    {
                        statements.Add(stmt);
                        Console.WriteLine($"[DEBUG] ParseClassBody: Added statement, total: {statements.Count}");
                    }
                    else
                    {
                        // Handle parse failures more carefully
                        Console.WriteLine($"[DEBUG] ParseClassBody: Failed to parse statement at {_position}, token: {CurrentToken?.Type} '{CurrentToken?.Value}'");
                        if (CurrentToken?.Type == GeneratedTokenType.DEDENT)
                        {
                            break; // End of class body
                        }
                        else if (CurrentToken != null)
                        {
                            Console.WriteLine($"[DEBUG] ParseClassBody: Skipping unparseable token to prevent infinite loop");
                            Advance();
                        }
                        else
                        {
                            break; // End of input
                        }
                    }
                }

                if (CurrentToken?.Type == GeneratedTokenType.DEDENT)
                {
                    Advance(); // consume DEDENT
                }
            }
            else
            {
                // Single line class body - parse one statement
                var stmt = ParseSimpleStmt();
                if (stmt != null)
                {
                    statements.Add(stmt);
                }
            }

            Console.WriteLine($"[DEBUG] ParseClassBody: Returning {statements.Count} statements");
            return statements;
        }

        /// <summary>
        /// class_def[stmt_ty]: 'class' a=NAME [type_params] b=['(' z=[arguments] ')'] ':' c=block
        /// </summary>
        public GeneratedStmt ParseClassDef()
        {
            Console.WriteLine($"[DEBUG] ParseClassDef: Starting at position {_position}, token: {CurrentToken?.Type} '{CurrentToken?.Value}'");

            // Expect 'class' keyword
            if (CurrentToken?.Type != GeneratedTokenType.NAME || CurrentToken?.Value != "class")
            {
                Console.WriteLine($"[DEBUG] ParseClassDef: Expected 'class' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                return null;
            }
            Advance(); // consume 'class'

            // Parse class name
            if (CurrentToken?.Type != GeneratedTokenType.NAME)
            {
                Console.WriteLine($"[DEBUG] ParseClassDef: Expected class name but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                return null;
            }
            var className = CurrentToken.Value;
            Advance(); // consume class name

            // Parse optional base classes and keyword arguments '(' [arguments] ')'
            var baseClasses = new List<object>();
            if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == "(")
            {
                Advance(); // consume '('
                
                // Parse class arguments (base classes and keyword arguments like metaclass=...)
                while (CurrentToken != null && !(CurrentToken.Type == GeneratedTokenType.OP && CurrentToken.Value == ")"))
                {
                    if (CurrentToken.Type == GeneratedTokenType.NAME)
                    {
                        var startPos = _position;
                        var firstToken = CurrentToken.Value;
                        Advance();
                        
                        // Check if this is a keyword argument (name=value)
                        if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == "=")
                        {
                            Advance(); // consume '='
                            
                            // Parse the value (expect a NAME for simple cases like metaclass=ABCMeta)
                            if (CurrentToken?.Type == GeneratedTokenType.NAME)
                            {
                                var value = CurrentToken.Value;
                                Advance();
                                
                                // CPython 3.12: Store as GeneratedExpr for consistent AST conversion
                                var keywordArg = new GeneratedExpr
                                {
                                    ExpressionType = "keyword",
                                    Value = new { 
                                        arg = firstToken, 
                                        value = new GeneratedExpr { ExpressionType = "Name", Value = new { value = value } }
                                    }
                                };
                                baseClasses.Add(keywordArg);
                                Console.WriteLine($"[DEBUG] ParseClassDef: Added keyword argument {firstToken}={value}");
                            }
                            else
                            {
                                Console.WriteLine($"[DEBUG] ParseClassDef: Expected value after '=' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                                break;
                            }
                        }
                        else
                        {
                            // Regular base class
                            baseClasses.Add(new { type = "name", value = firstToken });
                            Console.WriteLine($"[DEBUG] ParseClassDef: Added base class {firstToken}");
                        }
                    }
                    else
                    {
                        Console.WriteLine($"[DEBUG] ParseClassDef: Unexpected token in class arguments: {CurrentToken?.Type}:{CurrentToken?.Value}");
                        break;
                    }
                    
                    // Handle comma separator
                    if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == ",")
                    {
                        Advance(); // consume ','
                    }
                    else if (!(CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == ")"))
                    {
                        Console.WriteLine($"[DEBUG] ParseClassDef: Expected ',' or ')' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                        break;
                    }
                }
                
                // Expect closing ')'
                if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == ")")
                {
                    Advance(); // consume ')'
                }
                else
                {
                    Console.WriteLine($"[DEBUG] ParseClassDef: Expected ')' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                    return null;
                }
            }

            // Expect ':'
            if (CurrentToken?.Type != GeneratedTokenType.OP || CurrentToken?.Value != ":")
            {
                Console.WriteLine($"[DEBUG] ParseClassDef: Expected ':' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                return null;
            }
            Advance(); // consume ':'

            // Parse class body
            var body = ParseClassBody();
            if (body == null || body.Count == 0)
            {
                Console.WriteLine($"[DEBUG] ParseClassDef: Failed to parse class body");
                return null;
            }

            Console.WriteLine($"[DEBUG] ParseClassDef: Successfully parsed class '{className}' with {baseClasses.Count} base classes and {body.Count} statements");
            return new GeneratedStmt
            {
                StatementType = "class",
                ClassName = className,
                BaseClasses = baseClasses,
                Body = body
            };
        }

        /// <summary>
        /// try_stmt: 'try' ':' b=block ((except_block+ except_star_block* [finally_block]) | except_star_block+ [finally_block] | finally_block)
        /// </summary>
        public GeneratedStmt ParseTryStatement()
        {
            Console.WriteLine($"[DEBUG] ParseTryStatement: Starting at position {_position}, token: {CurrentToken?.Type} '{CurrentToken?.Value}'");

            // Expect 'try' keyword
            if (CurrentToken?.Type != GeneratedTokenType.NAME || CurrentToken?.Value != "try")
            {
                Console.WriteLine($"[DEBUG] ParseTryStatement: Expected 'try' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                return null;
            }
            Advance(); // consume 'try'

            // Expect ':'
            if (CurrentToken?.Type != GeneratedTokenType.OP || CurrentToken?.Value != ":")
            {
                Console.WriteLine($"[DEBUG] ParseTryStatement: Expected ':' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                return null;
            }
            Advance(); // consume ':'

            // Parse try body
            var tryBody = ParseBlock();
            if (tryBody == null || tryBody.Count == 0)
            {
                Console.WriteLine($"[DEBUG] ParseTryStatement: Failed to parse try body");
                return null;
            }

            // Parse except clauses (both except and except*)
            var exceptClauses = new List<object>();
            while (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken?.Value == "except")
            {
                Advance(); // consume 'except'
                var exceptionType = ""; // Optional exception type
                var exceptionName = ""; // Optional exception variable name
                var isExceptStar = false; // Track if this is except* clause

                // Check for except* syntax (PEP 654)
                if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == "*")
                {
                    isExceptStar = true;
                    Console.WriteLine($"[DEBUG] ParseTryStatement: Found except* clause");
                    Advance(); // consume '*'
                }

                // Parse optional exception type
                if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken?.Value != ":")
                {
                    exceptionType = CurrentToken.Value;
                    Advance();

                    // Parse optional 'as' variable
                    if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken?.Value == "as")
                    {
                        Advance(); // consume 'as'
                        if (CurrentToken?.Type == GeneratedTokenType.NAME)
                        {
                            exceptionName = CurrentToken.Value;
                            Advance();
                        }
                    }
                }

                // Expect ':'
                if (CurrentToken?.Type != GeneratedTokenType.OP || CurrentToken?.Value != ":")
                {
                    Console.WriteLine($"[DEBUG] ParseTryStatement: Expected ':' after except{(isExceptStar ? "*" : "")} but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                    return null;
                }
                Advance(); // consume ':'

                // Parse except body
                var exceptBody = ParseBlock();
                if (exceptBody == null || exceptBody.Count == 0)
                {
                    Console.WriteLine($"[DEBUG] ParseTryStatement: Failed to parse except{(isExceptStar ? "*" : "")} body");
                    return null;
                }

                exceptClauses.Add(new { type = exceptionType, name = exceptionName, body = exceptBody, isExceptStar = isExceptStar });
            }

            // Parse optional finally clause
            var finallyBody = new List<object>();
            if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken?.Value == "finally")
            {
                Advance(); // consume 'finally'
                // Expect ':'
                if (CurrentToken?.Type != GeneratedTokenType.OP || CurrentToken?.Value != ":")
                {
                    Console.WriteLine($"[DEBUG] ParseTryStatement: Expected ':' after finally but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                    return null;
                }
                Advance(); // consume ':'

                // Parse finally body
                finallyBody = ParseBlock();
                if (finallyBody == null)
                {
                    Console.WriteLine($"[DEBUG] ParseTryStatement: Failed to parse finally body");
                    return null;
                }
            }

            Console.WriteLine($"[DEBUG] ParseTryStatement: Successfully parsed try statement with {exceptClauses.Count} except clauses and {finallyBody.Count} finally statements");
            return new GeneratedStmt
            {
                StatementType = "try",
                TryBody = tryBody,
                ExceptClauses = exceptClauses,
                FinallyBody = finallyBody
            };
        }

        /// <summary>
        /// import_name[stmt_ty]: 'import' a=dotted_as_names
        /// </summary>
        public GeneratedStmt ParseImportStatement()
        {
            Console.WriteLine($"[DEBUG] ParseImportStatement: Starting at position {_position}, token: {CurrentToken?.Type} '{CurrentToken?.Value}'");

            // Expect 'import' keyword
            if (CurrentToken?.Type != GeneratedTokenType.NAME || CurrentToken?.Value != "import")
            {
                Console.WriteLine($"[DEBUG] ParseImportStatement: Expected 'import' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                return null;
            }
            Advance(); // consume 'import'

            // Parse module names (dotted_as_names)
            var modules = new List<object>();
            while (CurrentToken?.Type == GeneratedTokenType.NAME)
            {
                var moduleName = "";
                var asName = "";

                // Parse dotted name (e.g., os.path)
                while (CurrentToken?.Type == GeneratedTokenType.NAME)
                {
                    moduleName += CurrentToken.Value;
                    Advance();
                    if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == ".")
                    {
                        moduleName += ".";
                        Advance(); // consume '.'
                    }
                    else
                    {
                        break;
                    }
                }

                // Parse optional 'as' alias
                if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken?.Value == "as")
                {
                    Advance(); // consume 'as'
                    if (CurrentToken?.Type == GeneratedTokenType.NAME)
                    {
                        asName = CurrentToken.Value;
                        Advance();
                    }
                }

                modules.Add(new { name = moduleName, asname = asName });

                // Check for comma separator
                if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == ",")
                {
                    Advance(); // consume ','
                }
                else
                {
                    break;
                }
            }

            Console.WriteLine($"[DEBUG] ParseImportStatement: Successfully parsed import with {modules.Count} modules");
            return new GeneratedStmt
            {
                StatementType = "import",
                ImportModules = modules
            };
        }

        /// <summary>
        /// import_from[stmt_ty]: 'from' ... 'import' ...
        /// </summary>
        public GeneratedStmt ParseFromImportStatement()
        {
            Console.WriteLine($"[DEBUG] ParseFromImportStatement: Starting at position {_position}, token: {CurrentToken?.Type} '{CurrentToken?.Value}'");

            // Expect 'from' keyword
            if (CurrentToken?.Type != GeneratedTokenType.NAME || CurrentToken?.Value != "from")
            {
                Console.WriteLine($"[DEBUG] ParseFromImportStatement: Expected 'from' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                return null;
            }
            Advance(); // consume 'from'

            // Parse module name (with optional relative imports)
            var fromModule = "";
            var level = 0; // relative import level

            // Handle relative imports (. or ..)
            while (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == ".")
            {
                level++;
                fromModule += ".";
                Advance();
            }

            // Parse module name
            while (CurrentToken?.Type == GeneratedTokenType.NAME)
            {
                fromModule += CurrentToken.Value;
                Advance();
                if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == ".")
                {
                    fromModule += ".";
                    Advance(); // consume '.'
                }
                else
                {
                    break;
                }
            }

            // Expect 'import' keyword
            if (CurrentToken?.Type != GeneratedTokenType.NAME || CurrentToken?.Value != "import")
            {
                Console.WriteLine($"[DEBUG] ParseFromImportStatement: Expected 'import' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                return null;
            }
            Advance(); // consume 'import'

            // Parse import names
            var importNames = new List<object>();

            // Handle 'import *'
            if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == "*")
            {
                importNames.Add(new { Name = "*", AsName = (string)null });
                Advance();
            }
            else
            {
                // Parse import name list
                while (CurrentToken?.Type == GeneratedTokenType.NAME)
                {
                    var importName = CurrentToken.Value;
                    var asName = "";
                    Advance();

                    // Parse optional 'as' alias
                    if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken?.Value == "as")
                    {
                        Advance(); // consume 'as'
                        if (CurrentToken?.Type == GeneratedTokenType.NAME)
                        {
                            asName = CurrentToken.Value;
                            Advance();
                        }
                    }

                    importNames.Add(new { Name = importName, AsName = string.IsNullOrEmpty(asName) ? (string)null : asName });

                    // Check for comma separator
                    if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == ",")
                    {
                        Advance(); // consume ','
                    }
                    else
                    {
                        break;
                    }
                }
            }

            Console.WriteLine($"[DEBUG] ParseFromImportStatement: Successfully parsed 'from {fromModule} import' with {importNames.Count} names");
            return new GeneratedStmt
            {
                StatementType = "from_import",
                FromModule = fromModule,
                ImportLevel = level,
                ImportNames = importNames
            };
        }

        /// <summary>
        /// CPython 3.12 raise_stmt: 'raise' [expression ['from' expression]] | 'raise'
        /// </summary>
        public GeneratedStmt ParseRaiseStatement()
        {
            Console.WriteLine($"[DEBUG] ParseRaiseStatement: Starting at position {_position}, token: {CurrentToken?.Type} '{CurrentToken?.Value}'");

            // Expect 'raise' keyword
            if (CurrentToken?.Type != GeneratedTokenType.NAME || CurrentToken?.Value != "raise")
            {
                Console.WriteLine($"[DEBUG] ParseRaiseStatement: Expected 'raise' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                return null;
            }
            Advance(); // consume 'raise'

            // Check for expression after 'raise'
            GeneratedExpr exceptionExpr = null;
            GeneratedExpr fromExpr = null;

            // Parse optional exception expression
            if (CurrentToken != null && CurrentToken.Type != GeneratedTokenType.NEWLINE)
            {
                var exprResult = ParseExpression();
                exceptionExpr = (GeneratedExpr?)exprResult;
                if (exceptionExpr == null)
                {
                    Console.WriteLine($"[DEBUG] ParseRaiseStatement: Failed to parse exception expression");
                    return null;
                }

                // Check for optional 'from' clause
                if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken?.Value == "from")
                {
                    Advance(); // consume 'from'
                    var fromResult = ParseExpression();
                    fromExpr = (GeneratedExpr?)fromResult;
                    if (fromExpr == null)
                    {
                        Console.WriteLine($"[DEBUG] ParseRaiseStatement: Failed to parse 'from' expression");
                        return null;
                    }
                }
            }

            Console.WriteLine($"[DEBUG] ParseRaiseStatement: Successfully parsed raise statement");
            return new GeneratedStmt
            {
                StatementType = "raise",
                Value = new { ExceptionExpr = exceptionExpr, FromExpr = fromExpr }
            };
        }

        /// <summary>
        /// with_stmt: 'with' '(' a=with_item [',' with_item]* ')' ':' b=block | 'with' a=with_item [',' with_item]* ':' b=block
        /// </summary>
        public GeneratedStmt ParseWithStatement()
        {
            Console.WriteLine($"[DEBUG] ParseWithStatement: Starting at position {_position}, token: {CurrentToken?.Type} '{CurrentToken?.Value}'");

            // Expect 'with' keyword
            if (CurrentToken?.Type != GeneratedTokenType.NAME || CurrentToken?.Value != "with")
            {
                Console.WriteLine($"[DEBUG] ParseWithStatement: Expected 'with' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                return null;
            }
            Advance(); // consume 'with'

            // Check for optional parentheses
            bool hasParentheses = false;
            if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == "(")
            {
                hasParentheses = true;
                Advance(); // consume '('
            }

            // Parse with items
            var withItems = new List<object>();
            while (CurrentToken != null)
            {
                // Parse context expression
                var contextExpr = ParseExpression();
                if (contextExpr == null)
                {
                    Console.WriteLine($"[DEBUG] ParseWithStatement: Failed to parse context expression");
                    return null;
                }

                var asVar = "";
                // Parse optional 'as' target
                if (CurrentToken?.Type == GeneratedTokenType.NAME && CurrentToken?.Value == "as")
                {
                    Advance(); // consume 'as'
                    if (CurrentToken?.Type == GeneratedTokenType.NAME)
                    {
                        asVar = CurrentToken.Value;
                        Advance();
                    }
                }

                withItems.Add(new { context = contextExpr, target = asVar });

                // Check for comma separator
                if (CurrentToken?.Type == GeneratedTokenType.OP && CurrentToken?.Value == ",")
                {
                    Advance(); // consume ','
                }
                else
                {
                    break;
                }
            }

            // Check for closing parenthesis if we had opening one
            if (hasParentheses)
            {
                if (CurrentToken?.Type != GeneratedTokenType.OP || CurrentToken?.Value != ")")
                {
                    Console.WriteLine($"[DEBUG] ParseWithStatement: Expected ')' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                    return null;
                }
                Advance(); // consume ')'
            }

            // Expect ':'
            if (CurrentToken?.Type != GeneratedTokenType.OP || CurrentToken?.Value != ":")
            {
                Console.WriteLine($"[DEBUG] ParseWithStatement: Expected ':' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
                return null;
            }
            Advance(); // consume ':'

            // Parse with body
            var body = ParseBlock();
            if (body == null || body.Count == 0)
            {
                Console.WriteLine($"[DEBUG] ParseWithStatement: Failed to parse with body");
                return null;
            }

            Console.WriteLine($"[DEBUG] ParseWithStatement: Successfully parsed with statement with {withItems.Count} items and {body.Count} statements");
            return new GeneratedStmt
            {
                StatementType = "with",
                WithItems = withItems,
                Body = body
            };
        }

        // ========================================
        // Embedded PEG Interpreter - Complete Copy
        // This makes PyParser.cs independent from SharpPy.PegGenerator
        // ========================================

        // ========================================
        // PegParseResult Types - from IPegParseResult.cs
        // Note: ITokenInfo is defined in PyTokenizer.cs
        // ========================================

        /// <summary>
            /// Base interface for all PEG parse results to replace object? usage
            /// Provides type safety and better performance by avoiding boxing/unboxing
            /// </summary>
            public interface IPegParseResult
            {
                /// <summary>
                /// Whether the parsing was successful
                /// </summary>
                bool IsSuccess { get; }

                /// <summary>
                /// The position where parsing ended (for successful results)
                /// </summary>
                int EndPosition { get; }
            }

            /// <summary>
            /// Abstract base class for all parse results
            /// </summary>
            public abstract class PegParseResult : IPegParseResult
            {
                public bool IsSuccess { get; protected set; }
                public int EndPosition { get; protected set; }

                protected PegParseResult(bool isSuccess, int endPosition)
                {
                    IsSuccess = isSuccess;
                    EndPosition = endPosition;
                }
            }

            /// <summary>
            /// Represents a parsing failure - singleton pattern for efficiency
            /// </summary>
            public sealed class PegFailure : PegParseResult
            {
                public static readonly PegFailure Instance = new PegFailure();

                private PegFailure() : base(false, -1) { }

                public override string ToString() => "PegFailure";
            }

            /// <summary>
            /// Represents successful parsing of a token
            /// </summary>
            public sealed class PegTokenResult : PegParseResult
            {
                public ITokenInfo Token { get; }

                public PegTokenResult(ITokenInfo token, int endPosition)
                    : base(true, endPosition)
                {
                    Token = token ?? throw new ArgumentNullException(nameof(token));
                }

                public override string ToString() => $"PegTokenResult({Token.Type}:{Token.Value})";
            }

            /// <summary>
            /// Represents successful parsing of multiple items
            /// </summary>
            public sealed class PegListResult : PegParseResult
            {
                public IReadOnlyList<IPegParseResult> Items { get; }

                public PegListResult(IReadOnlyList<IPegParseResult> items, int endPosition)
                    : base(true, endPosition)
                {
                    Items = items ?? throw new ArgumentNullException(nameof(items));
                }

                public override string ToString() => $"PegListResult({Items.Count} items)";
            }

            /// <summary>
            /// Represents successful parsing that produced an AST node
            /// </summary>
            public sealed class PegAstResult : PegParseResult
            {
                public object AstNode { get; }

                public PegAstResult(object astNode, int endPosition)
                    : base(true, endPosition)
                {
                    AstNode = astNode ?? throw new ArgumentNullException(nameof(astNode));
                }

                public override string ToString() => $"PegAstResult({AstNode.GetType().Name})";
            }

            /// <summary>
            /// Represents Cut operation results for control flow
            /// </summary>
            public sealed class PegCutResult : PegParseResult
            {
                public bool IsCutFailure { get; }
                public IPegParseResult? InnerResult { get; }

                public PegCutResult(bool isCutFailure, IPegParseResult? innerResult, int endPosition)
                    : base(!isCutFailure, endPosition)
                {
                    IsCutFailure = isCutFailure;
                    InnerResult = innerResult;
                }

                public override string ToString() =>
                    IsCutFailure ? "PegCutFailure" : $"PegCutSuccess({InnerResult})";
            }

            /// <summary>
            /// Represents simple successful parsing (e.g., for optional matches)
            /// </summary>
            public sealed class PegSuccess : PegParseResult
            {
                public static readonly PegSuccess Instance = new PegSuccess(-1);

                public PegSuccess(int endPosition) : base(true, endPosition) { }

                public override string ToString() => $"PegSuccess(pos:{EndPosition})";
            }

            /// <summary>
            /// Represents successful parsing with an action result
            /// </summary>
            public sealed class PegActionResult : PegParseResult
            {
                public object ActionResult { get; }

                public PegActionResult(object actionResult, int endPosition)
                    : base(true, endPosition)
                {
                    ActionResult = actionResult ?? throw new ArgumentNullException(nameof(actionResult));
                }

                public override string ToString() => $"PegActionResult({ActionResult.GetType().Name})";
            }

        // ========================================
        // PegInterpreter Supporting Types
        // ========================================

        public class SimpleModule
        {
            public List<object>? Body { get; set; }
        }

        public class SimpleStmt
        {
            public string? Type { get; set; }
            public object? Data { get; set; }
        }

        public class SimpleExpr
        {
            public string? Type { get; set; }
            public object? Data { get; set; }
        }

        // ========================================
        // PegInterpreter - Complete Copy
        // Note: ContextType and ParserContext are defined in PyTokenizer.cs
        // ========================================

        public class PegInterpreter
            {
                private readonly EmbeddedGrammar _grammar;
                private readonly List<ITokenInfo> _tokens;
                private int _position;
                // ===== Performance Optimization: Cache Management =====
                private readonly Dictionary<(int, string), IPegParseResult> _memoCache = new();
                private readonly Queue<(int, string)> _cacheAccessOrder = new();
                private const int MAX_CACHE_SIZE = 10000; // CPython 3.12 style cache limit
                private int _cacheHits = 0;
                private int _cacheMisses = 0;

                private readonly Dictionary<string, object?> _variables = new();
                private readonly HashSet<(int, string)> _activeRules = new(); // Track active rules to prevent left recursion
                private readonly Dictionary<string, bool> _leftRecursiveRules = new(); // Cache for left-recursive rule detection
                private readonly Dictionary<string, IPegParseResult> _seedResults = new(); // Store seed results for left-recursive expansion

                // ===== Advanced Left Recursion Support (CPython 3.12 Style) =====
                private readonly Dictionary<string, HashSet<string>> _leftRecursiveDependencies = new(); // Track indirect dependencies
                private readonly HashSet<string> _currentRecursionStack = new(); // Track current recursion chain
                private readonly Dictionary<string, int> _recursionDepth = new(); // Track recursion depth for each rule
                private readonly Dictionary<int, int> _positionAttempts = new(); // Track attempts at each position for infinite loop detection

                // ===== Parser Context Stack (CPython 3.12 Style) =====
                private readonly Stack<ParserContext> _contextStack = new();
                private int _indentLevel = 0; // Track current indentation level

                public PegInterpreter(EmbeddedGrammar grammar, List<ITokenInfo> tokens)
                {
                    _grammar = grammar ?? throw new ArgumentNullException(nameof(grammar));
                    _tokens = tokens ?? throw new ArgumentNullException(nameof(tokens));
                    _position = 0;

                    // Initialize with module context
                    _contextStack.Push(new ParserContext(ContextType.Module, 0, 0, "<module>"));
                }

                /// <summary>
                /// Current token for parsing
                /// </summary>
                private ITokenInfo? CurrentToken => _position < _tokens.Count ? _tokens[_position] : null;

                /// <summary>
                /// Check if we're at end of tokens
                /// </summary>
                private bool IsAtEnd => _position >= _tokens.Count;

                /// <summary>
                /// Set the current position (for synchronization with external parser)
                /// </summary>
                public void SetPosition(int position)
                {
                    _position = position;
                    _positionAttempts.Clear();
                }

                /// <summary>
                /// Get the current position
                /// </summary>
                public int GetPosition()
                {
                    return _position;
                }

                /// <summary>
                /// Advance to next token
                /// </summary>
                private void Advance()
                {
                    if (_position < _tokens.Count)
                    {
                        _position++;
                        // Reset position attempt counter when we advance
                        _positionAttempts.Clear();
                    }
                }

                /// <summary>
                /// Mark current position for backtracking
                /// </summary>
                private int Mark()
                {
                    // Infinite loop detection - aggressive threshold for early detection
                    if (_positionAttempts.ContainsKey(_position))
                    {
                        _positionAttempts[_position]++;
                        if (_positionAttempts[_position] > 20) // Lower threshold for faster infinite loop detection
                        {
                            var tokenInfo = CurrentToken != null ? $"{CurrentToken.Type}('{CurrentToken.Value}')" : "EOF";
                            var activeRulesInfo = _activeRules.Count > 0 ?
                                string.Join(", ", _activeRules.Select(ar => $"{ar.Item2}@{ar.Item1}")) : "none";

                            throw new InvalidOperationException(
                                $"Infinite loop detected at token position {_position}. " +
                                $"Current token: {tokenInfo}. " +
                                $"Active rules: {activeRulesInfo}. " +
                                $"Attempts at this position: {_positionAttempts[_position]}");
                        }
                    }
                    else
                    {
                        _positionAttempts[_position] = 1;
                    }

                    return _position;
                }

                /// <summary>
                /// Reset position for backtracking
                /// </summary>
                private void Reset(int mark) => _position = mark;

                /// <summary>
                /// Check if a rule is left-recursive (direct, indirect, or mutual)
                /// CPython 3.12 compatible advanced left recursion detection
                /// </summary>
                private bool IsLeftRecursive(EmbeddedRule rule)
                {
                    if (_leftRecursiveRules.TryGetValue(rule.Name, out var cached))
                    {
                        return cached;
                    }

                    // Exclude certain rules from left recursion handling to preserve correct parsing behavior
                    // These rules rely on token boundaries (INDENT/DEDENT) that must be processed sequentially
                    if (rule.Name == "block" || rule.Name == "statements" || rule.Name == "statement")
                    {
                        Console.WriteLine($"[LEFT-REC] Excluding rule '{rule.Name}' from left recursion detection");
                        _leftRecursiveRules[rule.Name] = false;
                        return false;
                    }

                    // Clear recursion tracking for this check
                    _currentRecursionStack.Clear();
                    _recursionDepth.Clear();

                    // Check for any form of left recursion
                    var isLeftRec = CheckIndirectLeftRecursion(rule.Name, rule.Name);

                    Console.WriteLine($"[LEFT-REC] EmbeddedRule '{rule.Name}' left-recursive check: {isLeftRec}");
                    if (rule.Name == "primary")
                    {
                        Console.WriteLine($"[LEFT-REC] Primary rule has {rule.Alternatives.Count} alternatives");
                        for (int i = 0; i < rule.Alternatives.Count; i++)
                        {
                            var alt = rule.Alternatives[i];
                            var firstItem = alt.Items.Count > 0 ? alt.Items[0] : null;
                            var firstAtom = firstItem?.Atom;
                            var isRuleRef = firstAtom is EmbeddedRuleRef ruleRef;
                            var refName = isRuleRef ? ((EmbeddedRuleRef)firstAtom).Name : "not-ruleref";
                            Console.WriteLine($"[LEFT-REC]   Alt[{i}]: {alt.Items.Count} items, first={firstAtom?.GetType().Name}({refName})");
                        }
                    }

                    _leftRecursiveRules[rule.Name] = isLeftRec;
                    return isLeftRec;
                }

                /// <summary>
                /// Check for indirect left recursion using depth-first search
                /// This detects patterns like: A -> B, B -> A (mutual) or A -> B, B -> C, C -> A (indirect)
                /// </summary>
                private bool CheckIndirectLeftRecursion(string originalRule, string currentRule)
                {
                    // Prevent infinite recursion during detection
                    if (_currentRecursionStack.Contains(currentRule))
                    {
                        // Found a cycle - check if it involves the original rule
                        return currentRule == originalRule;
                    }

                    // Prevent too deep recursion
                    if (_recursionDepth.GetValueOrDefault(currentRule, 0) > 50)
                    {
                        return false;
                    }

                    _currentRecursionStack.Add(currentRule);
                    _recursionDepth[currentRule] = _recursionDepth.GetValueOrDefault(currentRule, 0) + 1;

                    try
                    {
                        // Get the rule definition
                        var rule = _grammar.Rules.FirstOrDefault(r => r.Name == currentRule);
                        if (rule == null) return false;

                        // Check each alternative
                        foreach (var alternative in rule.Alternatives)
                        {
                            if (alternative.Items.Count == 0) continue;

                            var firstItem = alternative.Items[0];
                            if (firstItem.Atom is EmbeddedRuleRef ruleRef)
                            {
                                var referencedRule = ruleRef.Name;

                                // Direct left recursion
                                if (referencedRule == originalRule)
                                {
                                    return true;
                                }

                                // Indirect left recursion - recurse
                                if (CheckIndirectLeftRecursion(originalRule, referencedRule))
                                {
                                    return true;
                                }
                            }
                        }

                        return false;
                    }
                    finally
                    {
                        _currentRecursionStack.Remove(currentRule);
                        if (_recursionDepth.ContainsKey(currentRule))
                        {
                            _recursionDepth[currentRule]--;
                            if (_recursionDepth[currentRule] <= 0)
                            {
                                _recursionDepth.Remove(currentRule);
                            }
                        }
                    }
                }

                /// <summary>
                /// Main entry point: Parse a rule by name
                /// </summary>
                public IPegParseResult ParseRule(string ruleName)
                {
        #if DEBUG_LOG
                    // Add debug for assignment-related rules
                    if (ruleName == "assignment" || ruleName == "simple_stmt" || ruleName == "simple_stmts")
                    {
                        Console.WriteLine($"[DEBUG] PEG ParseRule: Attempting '{ruleName}' at position {_position}, token: {CurrentToken?.Type} '{CurrentToken?.Value}'");
                    }
        #endif

                    // Check if this rule should be excluded in first pass
                    if (ShouldExcludeRuleInFirstPass(ruleName))
                    {
                        Console.WriteLine($"[2-PASS] Excluding invalid rule '{ruleName}' in first pass");
                        return PegFailure.Instance;
                    }

                    // Check memoization cache with performance tracking
                    var cacheKey = (_position, ruleName);
                    if (TryGetFromCache(cacheKey, out var cachedResult))
                    {
                        // Console.WriteLine($"[MEMO] Cache hit for {ruleName} at position {_position}");
                        return cachedResult;
                    }

                    // Find the rule in grammar
                    var rule = _grammar.Rules.FirstOrDefault(r => r.Name == ruleName);
                    if (rule == null)
                    {
                        // Console.WriteLine($"[DEBUG] EmbeddedRule not found: {ruleName}");
                        return PegFailure.Instance;
                    }

                    // Check if this is a left-recursive rule and handle specially
                    if (IsLeftRecursive(rule))
                    {
                        return ParseLeftRecursiveRule(ruleName, rule);
                    }

                    // Handle normal (non-left-recursive) rules
                    return ParseNormalRule(ruleName, rule);
                }

                /// <summary>
                /// Parse normal (non-left-recursive) rules
                /// </summary>
                private IPegParseResult ParseNormalRule(string ruleName, EmbeddedRule rule)
                {
                    var cacheKey = (_position, ruleName);

                    // Prevent infinite recursion by detecting active rules
                    if (_activeRules.Contains(cacheKey))
                    {
                        // Console.WriteLine($"[RECURSION] Infinite recursion detected for {ruleName} at position {_position}");
                        return PegFailure.Instance;
                    }

                    // Mark rule as active
                    _activeRules.Add(cacheKey);

                    try
                    {
                        // Console.WriteLine($"[DEBUG] Parsing normal rule: {ruleName} at position {_position}");

                        // Try each alternative (PEG ordered choice)
                        foreach (var alternative in rule.Alternatives)
                        {
                            var mark = Mark();
                            var result = ParseAlternative(alternative);

                            if (result is PegCutResult cutResult && cutResult.IsCutFailure)
                            {
                                // EmbeddedCut failed - no backtracking to other alternatives allowed
                                Console.WriteLine($"[DEBUG] EmbeddedRule {ruleName}: EmbeddedCut failure prevents trying other alternatives");
                                StoreInCache(cacheKey, PegFailure.Instance);
                                return PegFailure.Instance;
                            }
                            else if (result.IsSuccess)
                            {
                                // Success - cache and return
                                StoreInCache(cacheKey, result);
                                // Console.WriteLine($"[DEBUG] EmbeddedRule {ruleName} succeeded at position {_position}");
                                return result;
                            }

                            // Failed - backtrack
                            Reset(mark);
                        }

                        // No alternative succeeded
                        // Console.WriteLine($"[DEBUG] EmbeddedRule {ruleName} failed at position {_position}");
                        StoreInCache(cacheKey, PegFailure.Instance);
                        return PegFailure.Instance;
                    }
                    finally
                    {
                        // Remove rule from active set
                        _activeRules.Remove(cacheKey);
                    }
                }

                /// <summary>
                /// Parse left-recursive rules using seed parsing technique
                /// </summary>
                private IPegParseResult ParseLeftRecursiveRule(string ruleName, EmbeddedRule rule)
                {
                    var cacheKey = (_position, ruleName);

                    Console.WriteLine($"[LEFT-REC] Parsing left-recursive rule: {ruleName} at position {_position}, token: {CurrentToken?.Type}('{CurrentToken?.Value}')");

                    // Step 1: Find base alternatives (non-recursive ones)
                    var baseAlternatives = rule.Alternatives.Where(alt =>
                        !(alt.Items.Count > 0 &&
                          alt.Items[0].Atom is EmbeddedRuleRef ruleRef &&
                          ruleRef.Name == ruleName)).ToList();

                    // Step 2: Find recursive alternatives
                    var recursiveAlternatives = rule.Alternatives.Where(alt =>
                        alt.Items.Count > 0 &&
                        alt.Items[0].Atom is EmbeddedRuleRef ruleRef &&
                        ruleRef.Name == ruleName).ToList();

                    if (baseAlternatives.Count == 0)
                    {
                        // No base case - this shouldn't happen in well-formed grammar
                        // Console.WriteLine($"[LEFT-REC] No base alternatives found for {ruleName}");
                        return PegFailure.Instance;
                    }

                    // Step 3: Parse base alternatives to get initial seed
                    IPegParseResult? seed = null;
                    int seedPosition = _position;

                    foreach (var baseAlt in baseAlternatives)
                    {
                        var mark = Mark();
                        var result = ParseAlternative(baseAlt);

                        if (result.IsSuccess)
                        {
                            seed = result;
                            seedPosition = _position;
                            Console.WriteLine($"[LEFT-REC] Found seed for {ruleName} at position {seedPosition}: {seed}");
                            break;
                        }

                        Reset(mark);
                    }

                    if (seed == null)
                    {
                        // No base case matched
                        StoreInCache(cacheKey, PegFailure.Instance);
                        return PegFailure.Instance;
                    }

                    // Step 4: Iteratively expand the seed using recursive alternatives
                    const int maxIterations = 1000; // Prevent infinite loops
                    int iterationCount = 0;
                    int lastPosition = seedPosition;

                    while (iterationCount < maxIterations)
                    {
                        iterationCount++;
                        var expandedSeed = seed;
                        var expandedPosition = seedPosition;
                        var foundExpansion = false;

                        foreach (var recursiveAlt in recursiveAlternatives)
                        {
                            // Reset to seed position for each recursive alternative
                            Reset(seedPosition);

                            // Temporarily set the seed result for this rule
                            var tempCacheKey = (_position, ruleName);
                            _memoCache[tempCacheKey] = seed; // Direct assignment for left recursion

                            try
                            {
                                var result = ParseAlternative(recursiveAlt);
                                // CPython-style check: must advance position to be a valid expansion
                                if (result.IsSuccess && _position > seedPosition)
                                {
                                    // Found a longer parse - update seed
                                    expandedSeed = result;
                                    expandedPosition = _position;
                                    foundExpansion = true;
                                    Console.WriteLine($"[LEFT-REC] Iteration {iterationCount}: Expanded seed for {ruleName} from pos {seedPosition} to {_position}");
                                    break;
                                }
                            }
                            finally
                            {
                                // Remove temporary cache entry
                                _memoCache.Remove(tempCacheKey);
                            }
                        }

                        if (!foundExpansion)
                        {
                            // No more expansions possible - terminate normally
                            Console.WriteLine($"[LEFT-REC] No expansion found for {ruleName} at iteration {iterationCount}, terminating");
                            break;
                        }

                        // CPython-style progress check: if position didn't advance, we're stuck
                        if (expandedPosition <= lastPosition)
                        {
                            Console.WriteLine($"[LEFT-REC] Position didn't advance for {ruleName} (was {lastPosition}, now {expandedPosition}), terminating to prevent infinite loop");
                            break;
                        }

                        // Update seed for next iteration
                        seed = expandedSeed;
                        lastPosition = seedPosition;  // Store previous seed position
                        seedPosition = expandedPosition;  // New seed position
                    }

                    if (iterationCount >= maxIterations)
                    {
                        Console.WriteLine($"[LEFT-REC] WARNING: Maximum iterations ({maxIterations}) reached for rule {ruleName}, terminating to prevent infinite loop");
                    }

                    // Step 5: Set final position and cache result
                    _position = seedPosition;
                    StoreInCache(cacheKey, seed);

                    Console.WriteLine($"[LEFT-REC] Final result for {ruleName}: {seed} at position {seedPosition}");
                    return seed;
                }

                /// <summary>
                /// Parse a single alternative (sequence of items)
                /// </summary>
                private IPegParseResult ParseAlternative(EmbeddedAlternative alternative)
                {
                    var results = new List<IPegParseResult>();
                    var variables = new Dictionary<string, IPegParseResult>();

                    // Console.WriteLine($"[DEBUG] Parsing alternative with {alternative.Items.Count} items");

                    // Parse each item in sequence
                    foreach (var item in alternative.Items)
                    {
                        var result = ParseItem(item);

                        // Handle cut operations
                        if (result is PegCutResult cutResult)
                        {
                            if (!cutResult.IsCutFailure)
                            {
                                // EmbeddedCut succeeded - use the result and continue with committed parse
                                Console.WriteLine($"[DEBUG] EmbeddedCut succeeded, committed to this alternative");
                                var innerResult = cutResult.InnerResult ?? PegSuccess.Instance;
                                results.Add(innerResult);
                                // Store variable binding if item has a name
                                if (!string.IsNullOrEmpty(item.Name))
                                {
                                    variables[item.Name] = innerResult;
                                }
                                // Continue parsing rest of the alternative
                                continue;
                            }
                            else
                            {
                                // EmbeddedCut failed - this prevents backtracking to other alternatives
                                Console.WriteLine($"[DEBUG] EmbeddedCut failed at position {cutResult.EndPosition}, no backtracking allowed");
                                return cutResult; // Propagate cut failure up to prevent backtracking
                            }
                        }
                        else if (!result.IsSuccess)
                        {
                            // EmbeddedItem failed - alternative fails
                            // Console.WriteLine($"[DEBUG] EmbeddedItem failed in alternative");
                            return PegFailure.Instance;
                        }

                        results.Add(result);

                        // Store variable binding if item has a name
                        if (!string.IsNullOrEmpty(item.Name))
                        {
                            variables[item.Name] = result;
                            // Console.WriteLine($"[DEBUG] Variable binding: {item.Name} = {result}");
                        }
                    }

                    // All items succeeded - execute action
                    return ExecuteAction(alternative.Action, variables, results);
                }

                /// <summary>
                /// Parse a single item (with optional variable binding)
                /// </summary>
                private IPegParseResult ParseItem(EmbeddedItem item)
                {
                    // Console.WriteLine($"[DEBUG] Parsing item: {item.Name}={item.Atom}");
                    return ParseAtom(item.Atom);
                }

                /// <summary>
                /// Parse an atomic expression based on its type
                /// </summary>
                private IPegParseResult ParseAtom(EmbeddedAtom atom)
                {
                    switch (atom)
                    {
                        case EmbeddedStringLiteral stringLiteral:
                            return ParseStringLiteral(stringLiteral);

                        case EmbeddedRuleRef ruleRef:
                            // Check if this is a token type (uppercase name)
                            if (IsTokenType(ruleRef.Name))
                            {
                                return ParseTokenType(ruleRef.Name);
                            }
                            return ParseRule(ruleRef.Name);

                        case EmbeddedOptional optional:
                            return ParseOptional(optional);

                        case EmbeddedGroup group:
                            return ParseGroup(group);

                        case EmbeddedZeroOrMore zeroOrMore:
                            return ParseZeroOrMore(zeroOrMore);

                        case EmbeddedOneOrMore oneOrMore:
                            return ParseOneOrMore(oneOrMore);

                        case EmbeddedPositiveLookahead positiveLookahead:
                            return ParsePositiveLookahead(positiveLookahead);

                        case EmbeddedNegativeLookahead negativeLookahead:
                            return ParseNegativeLookahead(negativeLookahead);

                        case EmbeddedCut cut:
                            return ParseCut(cut);

                        default:
                            Console.WriteLine($"[ERROR] Unknown atom type: {atom.GetType()}");
                            return PegFailure.Instance;
                    }
                }

                /// <summary>
                /// Parse string literal (keywords and operators)
                /// </summary>
                private IPegParseResult ParseStringLiteral(EmbeddedStringLiteral stringLiteral)
                {
                    var expected = stringLiteral.Value;
                    var current = CurrentToken;

                    Console.WriteLine($"[DEBUG] Expecting string literal: '{expected}', current token: {current?.Type}('{current?.Value}')");

                    if (current == null) return PegFailure.Instance;

                    // Handle keywords (they come as NAME tokens)
                    if (IsKeyword(expected))
                    {
                        if (current.Type.ToString() == "NAME" && current.Value == expected)
                        {
                            Advance();
                            return new PegTokenResult(current, _position);
                        }
                    }
                    // Handle operators and punctuation (CPython 3.12: all operators are OP tokens)
                    else
                    {
                        // Check if token is OP type with matching value
                        if (current.Type.ToString() == "OP" && current.Value == expected)
                        {
                            Advance();
                            return new PegTokenResult(current, _position);
                        }
                    }

                    return PegFailure.Instance;
                }

                /// <summary>
                /// Parse optional expression [expr]
                /// </summary>
                private IPegParseResult ParseOptional(EmbeddedOptional optional)
                {
                    // Console.WriteLine($"[DEBUG] Parsing optional: [{optional.Expression}]");

                    var mark = Mark();
                    var result = ParseAtom(optional.Expression);

                    if (!result.IsSuccess)
                    {
                        // EmbeddedOptional failed - reset and return empty success
                        Reset(mark);
                        // Console.WriteLine($"[DEBUG] EmbeddedOptional failed, continuing");
                        return new PegSuccess(_position); // Return success to indicate optional succeeded
                    }

                    // Console.WriteLine($"[DEBUG] EmbeddedOptional succeeded");
                    return result;
                }

                /// <summary>
                /// Parse group (alternatives in parentheses)
                /// </summary>
                private IPegParseResult ParseGroup(EmbeddedGroup group)
                {
                    Console.WriteLine($"[DEBUG] Parsing group with {group.Alternatives.Count} alternatives");

                    // Try each alternative in the group
                    foreach (var alternative in group.Alternatives)
                    {
                        var mark = Mark();
                        var result = ParseAlternative(alternative);

                        if (result.IsSuccess)
                        {
                            return result;
                        }

                        Reset(mark);
                    }

                    return PegFailure.Instance;
                }

                /// <summary>
                /// Parse zero or more repetitions expr*
                /// </summary>
                private IPegParseResult ParseZeroOrMore(EmbeddedZeroOrMore zeroOrMore)
                {
                    Console.WriteLine($"[DEBUG] Parsing zero or more: {zeroOrMore.Expression}*");

                    var results = new List<IPegParseResult>();

                    while (true)
                    {
                        var mark = Mark();
                        var result = ParseAtom(zeroOrMore.Expression);

                        if (!result.IsSuccess)
                        {
                            Reset(mark);
                            break;
                        }

                        results.Add(result);
                    }

                    Console.WriteLine($"[DEBUG] Zero or more matched {results.Count} items");
                    return new PegListResult(results, _position);
                }

                /// <summary>
                /// Parse one or more repetitions expr+
                /// </summary>
                private IPegParseResult ParseOneOrMore(EmbeddedOneOrMore oneOrMore)
                {
                    Console.WriteLine($"[DEBUG] Parsing one or more: {oneOrMore.Expression}+");

                    var results = new List<IPegParseResult>();

                    // Must match at least once
                    var firstResult = ParseAtom(oneOrMore.Expression);
                    if (!firstResult.IsSuccess)
                    {
                        return PegFailure.Instance;
                    }

                    results.Add(firstResult);

                    // Then zero or more additional matches
                    while (true)
                    {
                        var mark = Mark();
                        var result = ParseAtom(oneOrMore.Expression);

                        if (!result.IsSuccess)
                        {
                            Reset(mark);
                            break;
                        }

                        results.Add(result);
                    }

                    Console.WriteLine($"[DEBUG] One or more matched {results.Count} items");
                    return new PegListResult(results, _position);
                }

                /// <summary>
                /// Parse positive lookahead &expr
                /// </summary>
                private IPegParseResult ParsePositiveLookahead(EmbeddedPositiveLookahead positiveLookahead)
                {
                    Console.WriteLine($"[DEBUG] Parsing positive lookahead: &{positiveLookahead.Expression}");

                    var mark = Mark();
                    var result = ParseAtom(positiveLookahead.Expression);

                    // Always reset position (lookahead doesn't consume)
                    Reset(mark);

                    // Return success/failure based on whether expression matched
                    return result.IsSuccess ? new PegSuccess(_position) : PegFailure.Instance;
                }

                /// <summary>
                /// Parse negative lookahead !expr
                /// </summary>
                private IPegParseResult ParseNegativeLookahead(EmbeddedNegativeLookahead negativeLookahead)
                {
                    Console.WriteLine($"[DEBUG] Parsing negative lookahead: !{negativeLookahead.Expression}");

                    var mark = Mark();
                    var result = ParseAtom(negativeLookahead.Expression);

                    // Always reset position (lookahead doesn't consume)
                    Reset(mark);

                    // Return success if expression did NOT match
                    return !result.IsSuccess ? new PegSuccess(_position) : PegFailure.Instance;
                }

                /// <summary>
                /// Parse cut operator ~expr - prevents backtracking beyond this point
                /// In CPython 3.12, cut operator commits to the current alternative and
                /// prevents exploring other alternatives in case of failure
                /// </summary>
                private IPegParseResult ParseCut(EmbeddedCut cut)
                {
                    Console.WriteLine($"[DEBUG] ParseCut: EmbeddedCut operator encountered at position {_position}");

                    // Save the current position - this is our "cut point"
                    var cutPosition = _position;

                    // Try to parse the expression after the cut
                    var result = ParseAtom(cut.Expression);

                    if (result.IsSuccess)
                    {
                        Console.WriteLine($"[DEBUG] ParseCut: Expression after cut succeeded, committing to this path");
                        // Success - mark this as a "committed" parse by setting a special flag
                        // The cut succeeds and we return the result
                        return CreateCutSuccess(result, cutPosition);
                    }
                    else
                    {
                        Console.WriteLine($"[DEBUG] ParseCut: Expression after cut failed, cut prevents backtracking");
                        // Failure after cut - this should prevent backtracking to earlier alternatives
                        // In a full implementation, this would throw a special exception or set a flag
                        // For now, we'll return a special failure marker
                        return CreateCutFailure(cutPosition);
                    }
                }

                /// <summary>
                /// Helper methods for creating cut results
                /// </summary>
                private static IPegParseResult CreateCutSuccess(IPegParseResult result, int cutPosition)
                {
                    return new PegCutResult(false, result, cutPosition);
                }

                private static IPegParseResult CreateCutFailure(int cutPosition)
                {
                    return new PegCutResult(true, null, cutPosition);
                }

                // ===== Performance Optimization: Cache Management Methods =====

                /// <summary>
                /// Try to get value from cache with LRU tracking
                /// </summary>
                private bool TryGetFromCache((int, string) key, out IPegParseResult result)
                {
                    if (_memoCache.TryGetValue(key, out result))
                    {
                        _cacheHits++;
                        // Update access order for LRU
                        UpdateCacheAccess(key);
                        return true;
                    }

                    _cacheMisses++;
                    return false;
                }

                /// <summary>
                /// Store value in cache with size management
                /// </summary>
                private void StoreInCache((int, string) key, IPegParseResult value)
                {
                    // Evict oldest entries if cache is full
                    while (_memoCache.Count >= MAX_CACHE_SIZE)
                    {
                        EvictOldestCacheEntry();
                    }

                    _memoCache[key] = value;
                    _cacheAccessOrder.Enqueue(key);
                }

                /// <summary>
                /// Update cache access order for LRU
                /// </summary>
                private void UpdateCacheAccess((int, string) key)
                {
                    // For simplicity, we just add to queue again
                    // In a full LRU implementation, we would remove from middle and add to end
                    _cacheAccessOrder.Enqueue(key);
                }

                /// <summary>
                /// Evict oldest cache entry (LRU policy)
                /// </summary>
                private void EvictOldestCacheEntry()
                {
                    if (_cacheAccessOrder.Count > 0)
                    {
                        var oldestKey = _cacheAccessOrder.Dequeue();
                        _memoCache.Remove(oldestKey);
                        Console.WriteLine($"[CACHE] Evicted entry: {oldestKey}");
                    }
                }

                /// <summary>
                /// Get cache performance statistics
                /// </summary>
                public string GetCacheStats()
                {
                    var hitRate = _cacheHits + _cacheMisses > 0
                        ? (double)_cacheHits / (_cacheHits + _cacheMisses) * 100
                        : 0;

                    return $"Cache Stats: {_cacheHits} hits, {_cacheMisses} misses, " +
                           $"{hitRate:F1}% hit rate, {_memoCache.Count}/{MAX_CACHE_SIZE} entries";
                }

                /// <summary>
                /// Clear performance counters
                /// </summary>
                public void ResetCacheStats()
                {
                    _cacheHits = 0;
                    _cacheMisses = 0;
                }

                /// <summary>
                /// Execute action with parsed results and variable bindings
                /// </summary>
                private IPegParseResult ExecuteAction(string? action, Dictionary<string, IPegParseResult> variables, List<IPegParseResult> results)
                {
                    if (string.IsNullOrEmpty(action))
                    {
                        // No action - return first result or success marker
                        return results.FirstOrDefault() ?? new PegSuccess(_position);
                    }

                    Console.WriteLine($"[DEBUG] Executing action: {action}");
                    Console.WriteLine($"[DEBUG] Variables: {string.Join(", ", variables.Select(kv => $"{kv.Key}={kv.Value}"))}");
                    Console.WriteLine($"[DEBUG] Results count: {results.Count}");

                    // Parse the action to generate appropriate AST node
                    return ParseAction(action, variables, results);
                }

                /// <summary>
                /// Parse semantic action and create corresponding AST node
                /// </summary>
                private IPegParseResult ParseAction(string action, Dictionary<string, IPegParseResult> variables, List<IPegParseResult> results)
                {
                    // Handle common action patterns
                    if (action.Contains("_PyPegen_set_expr_context"))
                    {
                        // Expression context setting: _PyPegen_set_expr_context(p, a, Store)
                        // Just return the variable 'a' as this is primarily for context setting
                        if (variables.ContainsKey("a"))
                        {
                            return variables["a"];
                        }
                        return results.FirstOrDefault() ?? new PegSuccess(_position);
                    }
                    else if (action.Contains("CHECK_VERSION"))
                    {
                        // Handle version checks - for Python 3.12 interpreter, allow all modern features
                        // Extract the version requirement (typically version 6 for annotations)
        #if DEBUG_LOG
                        Console.WriteLine($"[DEBUG] PEG: CHECK_VERSION called, allowing modern Python features");
        #endif

                        // For now, always allow version checks and return the actual AST construction
                        if (action.Contains("_PyAST_AnnAssign"))
                        {
                            // Annotated Assignment: a=NAME ':' b=expression c=['=' d=annotated_rhs { d }]
                            var stmt = new SimpleStmt
                            {
                                Type = "ann_assign",
                                Data = new {
                                    Target = variables.ContainsKey("a") ? variables["a"] : null,
                                    Annotation = variables.ContainsKey("b") ? variables["b"] : null,
                                    Value = variables.ContainsKey("c") ? variables["c"] : null,
                                    Simple = 1 // Always 1 for NAME annotations as per CPython
                                }
                            };
        #if DEBUG_LOG
                            Console.WriteLine($"[DEBUG] PEG: Created ann_assign statement");
        #endif
                            return new PegAstResult(stmt, _position);
                        }

                        // For other version checks, continue with normal processing
                        return results.FirstOrDefault() ?? new PegSuccess(_position);
                    }
                    else if (action.Contains("_PyAST_AnnAssign"))
                    {
                        // Annotated Assignment: a=NAME ':' b=expression c=['=' d=annotated_rhs { d }]
                        var stmt = new SimpleStmt
                        {
                            Type = "ann_assign",
                            Data = new {
                                Target = variables.ContainsKey("a") ? variables["a"] : null,
                                Annotation = variables.ContainsKey("b") ? variables["b"] : null,
                                Value = variables.ContainsKey("c") ? variables["c"] : null,
                                Simple = 1 // Always 1 for NAME annotations as per CPython
                            }
                        };
                        return new PegAstResult(stmt, _position);
                    }
                    else if (action.Contains("_PyAST_TryStar"))
                    {
                        // Try statement with except* handlers (Python 3.11+ Exception Groups)
                        var stmt = new SimpleStmt
                        {
                            Type = "try_star",
                            Data = new {
                                body = variables.ContainsKey("b") ? variables["b"] : null,
                                handlers = variables.ContainsKey("ex") ? variables["ex"] : null,
                                orelse = variables.ContainsKey("el") ? variables["el"] : null,
                                finalbody = variables.ContainsKey("f") ? variables["f"] : null
                            }
                        };
        #if DEBUG_LOG
                        Console.WriteLine($"[DEBUG] PEG: Created try_star statement");
        #endif
                        return new PegAstResult(stmt, _position);
                    }
                    else if (action.Contains("_PyAST_Try"))
                    {
                        // Regular try statement
                        var stmt = new SimpleStmt
                        {
                            Type = "try",
                            Data = new {
                                body = variables.ContainsKey("b") ? variables["b"] : null,
                                handlers = variables.ContainsKey("ex") ? variables["ex"] : null,
                                orelse = variables.ContainsKey("el") ? variables["el"] : null,
                                finalbody = variables.ContainsKey("f") ? variables["f"] : null
                            }
                        };
        #if DEBUG_LOG
                        Console.WriteLine($"[DEBUG] PEG: Created try statement");
        #endif
                        return new PegAstResult(stmt, _position);
                    }
                    else if (action.Contains("_PyAST_ExceptHandler"))
                    {
                        // Exception handler: 'except' [expression ['as' NAME]] ':' block
                        var handler = new SimpleStmt
                        {
                            Type = "except_handler",
                            Data = new {
                                type = variables.ContainsKey("e") ? variables["e"] : null,
                                name = variables.ContainsKey("t") ? variables["t"] : null,
                                body = variables.ContainsKey("b") ? variables["b"] : null
                            }
                        };
        #if DEBUG_LOG
                        Console.WriteLine($"[DEBUG] PEG: Created except_handler");
        #endif
                        return new PegAstResult(handler, _position);
                    }
                    else if (action.Contains("_PyAST_Assign"))
                    {
                        // Assignment: a[asdl_expr_seq*]=(z=star_targets '=' { z })+ b=(yield_expr | star_expressions)
                        var stmt = new SimpleStmt
                        {
                            Type = "assignment",
                            Data = new {
                                Targets = variables.ContainsKey("a") ? variables["a"] : null,
                                Value = variables.ContainsKey("b") ? variables["b"] : null
                            }
                        };
                        return new PegAstResult(stmt, _position);
                    }
                    else if (action.Contains("_PyAST_Module"))
                    {
                        // Module: statements+
                        var module = new SimpleModule
                        {
                            Body = variables.ContainsKey("a") ? variables["a"] as List<object> : new List<object>()
                        };
                        return new PegAstResult(module, _position);
                    }
                    else if (action.Contains("_PyAST_Name"))
                    {
                        // Name expression: NAME
                        var expr = new SimpleExpr
                        {
                            Type = "name",
                            Data = variables.ContainsKey("id") ? variables["id"] : null
                        };
                        return new PegAstResult(expr, _position);
                    }
                    else if (action.Contains("_PyAST_Constant") || action.Contains("_PyAST_Num"))
                    {
                        // Constant/Number expression
                        var expr = new SimpleExpr
                        {
                            Type = "constant",
                            Data = variables.ContainsKey("value") ? variables["value"] : null
                        };
                        return new PegAstResult(expr, _position);
                    }
                    else if (action.Contains("_PyAST_BinOp"))
                    {
                        // Binary operation: left op right
                        var expr = new SimpleExpr
                        {
                            Type = "binop",
                            Data = new {
                                Left = variables.ContainsKey("left") ? variables["left"] : null,
                                Op = variables.ContainsKey("op") ? variables["op"] : null,
                                Right = variables.ContainsKey("right") ? variables["right"] : null
                            }
                        };
                        return new PegAstResult(expr, _position);
                    }
                    else if (action.Contains("_PyAST_TypeAlias"))
                    {
                        // Type alias: "type" n=NAME t=[type_params] '=' b=expression
                        var stmt = new SimpleStmt
                        {
                            Type = "type_alias",
                            Data = new {
                                Name = variables.ContainsKey("n") ? variables["n"] : null,
                                TypeParams = variables.ContainsKey("t") ? variables["t"] : null,
                                Value = variables.ContainsKey("b") ? variables["b"] : null
                            }
                        };
                        return new PegAstResult(stmt, _position);
                    }
                    else if (action.Contains("_PyAST_AsyncFunctionDef"))
                    {
                        // Async function definition: ASYNC 'def' n=NAME params=[params] b=block
                        var stmt = new SimpleStmt
                        {
                            Type = "async_function_def",
                            Data = new {
                                Name = variables.ContainsKey("n") ? variables["n"] : null,
                                Params = variables.ContainsKey("params") ? variables["params"] : null,
                                Body = variables.ContainsKey("b") ? variables["b"] : null,
                                TypeParams = variables.ContainsKey("t") ? variables["t"] : null,
                                Returns = variables.ContainsKey("a") ? variables["a"] : null
                            }
                        };
                        return new PegAstResult(stmt, _position);
                    }
                    else if (action.Contains("_PyAST_Break"))
                    {
                        // Break statement: 'break' { _PyAST_Break(EXTRA) }
                        var stmt = new SimpleStmt
                        {
                            Type = "break",
                            Data = null
                        };
                        return new PegAstResult(stmt, _position);
                    }
                    else if (action.Contains("_PyAST_Continue"))
                    {
                        // Continue statement: 'continue' { _PyAST_Continue(EXTRA) }
                        var stmt = new SimpleStmt
                        {
                            Type = "continue",
                            Data = null
                        };
                        return new PegAstResult(stmt, _position);
                    }

                    // Default: return generic success marker for now
                    Console.WriteLine($"[DEBUG] Unhandled action pattern: {action}");
                    var defaultResult = new { Action = action, Variables = variables, Results = results };
                    return new PegActionResult(defaultResult, _position);
                }

                /// <summary>
                /// Check if a name refers to a token type (from GeneratedTokenType enum)
                /// </summary>
                private bool IsTokenType(string name)
                {
                    // Check if the name corresponds to a GeneratedTokenType enum value
                    return Enum.TryParse<GeneratedTokenType>(name, out _);
                }

                /// <summary>
                /// Parse a token type by matching current token against expected type
                /// CPython 3.12: NAME tokens cannot be keywords
                /// </summary>
                private IPegParseResult ParseTokenType(string tokenType)
                {
                    var current = CurrentToken;
                    if (current == null) return PegFailure.Instance;

                    Console.WriteLine($"[DEBUG] Expecting token type: {tokenType}, current token: {current.Type}('{current.Value}')");

                    if (current.Type.ToString() == tokenType)
                    {
                        // CPython 3.12: NAME tokens cannot be keywords (in, not, for, etc.)
                        if (tokenType == "NAME" && IsKeyword(current.Value))
                        {
                            Console.WriteLine($"[DEBUG] Rejecting keyword '{current.Value}' as NAME token");
                            return PegFailure.Instance;
                        }

                        Advance();
                        return new PegTokenResult(current, _position);
                    }

                    return PegFailure.Instance;
                }

                /// <summary>
                /// Check if string is a Python keyword
                /// </summary>
                private bool IsKeyword(string value)
                {
                    var keywords = new HashSet<string>
                    {
                        "and", "as", "assert", "async", "await", "break", "case", "class", "continue",
                        "def", "del", "elif", "else", "except", "False", "finally", "for", "from",
                        "global", "if", "import", "in", "is", "lambda", "match", "None", "nonlocal",
                        "not", "or", "pass", "raise", "return", "True", "try", "type", "while", "with", "yield"
                    };
                    return keywords.Contains(value);
                }

                /// <summary>
                /// Map string literals to token types
                /// </summary>

                // ===== 2-Pass Parsing Support for Invalid Rules =====

                /// <summary>
                /// Indicates whether we're in the first pass (excluding invalid rules) or second pass (including invalid rules)
                /// </summary>
                private bool _isFirstPass = true;
                private int _firstPassFailurePosition = -1;

                /// <summary>
                /// Parse a rule with 2-pass support for better error messages
                /// This is the new main entry point that handles invalid rules properly
                /// </summary>
                public IPegParseResult ParseRuleWithTwoPass(string ruleName)
                {
                    Console.WriteLine($"[2-PASS] Starting 2-pass parsing for rule: {ruleName}");

                    // First pass: exclude invalid rules
                    _isFirstPass = true;
                    _firstPassFailurePosition = -1;
                    var firstPassPosition = _position;

                    var result = ParseRule(ruleName);
                    if (result.IsSuccess)
                    {
                        Console.WriteLine($"[2-PASS] First pass succeeded for rule: {ruleName}");
                        return result;
                    }

                    // First pass failed - record failure position
                    _firstPassFailurePosition = _position;
                    Console.WriteLine($"[2-PASS] First pass failed for rule: {ruleName} at position {_firstPassFailurePosition}");

                    // Reset position for second pass
                    _position = firstPassPosition;
                    _memoCache.Clear(); // Clear memoization cache for second pass

                    // Second pass: include invalid rules for better error messages
                    _isFirstPass = false;
                    Console.WriteLine($"[2-PASS] Starting second pass (with invalid rules) for rule: {ruleName}");

                    result = ParseRule(ruleName);
                    if (result.IsSuccess)
                    {
                        Console.WriteLine($"[2-PASS] Second pass succeeded for rule: {ruleName}");
                        return result;
                    }

                    // Both passes failed - use first pass failure position for more accurate error location
                    if (_firstPassFailurePosition >= 0)
                    {
                        _position = _firstPassFailurePosition;
                        Console.WriteLine($"[2-PASS] Both passes failed, using first pass failure position: {_firstPassFailurePosition}");
                    }

                    return PegFailure.Instance;
                }

                /// <summary>
                /// Check if a rule should be excluded in the first pass (is it an invalid rule?)
                /// </summary>
                private bool ShouldExcludeRuleInFirstPass(string ruleName)
                {
                    return _isFirstPass && ruleName.StartsWith("invalid_");
                }

                // ===== Parser Context Management (CPython 3.12 Style) =====

                /// <summary>
                /// Push a new context onto the context stack
                /// </summary>
                private void PushContext(ContextType type, string? name = null)
                {
                    var newLevel = _contextStack.Count > 0 ? _contextStack.Peek().NestingLevel + 1 : 0;
                    var context = new ParserContext(type, newLevel, _position, name);
                    _contextStack.Push(context);

                    Console.WriteLine($"[CONTEXT] Pushed {context}");
                }

                /// <summary>
                /// Pop the current context from the context stack
                /// </summary>
                private ParserContext? PopContext()
                {
                    if (_contextStack.Count > 1) // Keep module context
                    {
                        var context = _contextStack.Pop();
                        Console.WriteLine($"[CONTEXT] Popped {context}");
                        return context;
                    }
                    return null;
                }

                /// <summary>
                /// Check if we're currently in a specific context type
                /// </summary>
                private bool IsInContext(ContextType type)
                {
                    return _contextStack.Any(ctx => ctx.Type == type);
                }

                /// <summary>
                /// Get the current top context
                /// </summary>
                private ParserContext? GetCurrentContext()
                {
                    return _contextStack.Count > 0 ? _contextStack.Peek() : null;
                }

                /// <summary>
                /// Validate if a statement is allowed in the current context
                /// </summary>
                private void ValidateStatementContext(string statementType)
                {
                    switch (statementType)
                    {
                        case "return":
                            if (!IsInContext(ContextType.Function) && !IsInContext(ContextType.Lambda))
                            {
                                throw new InvalidOperationException("SyntaxError: 'return' outside function");
                            }
                            break;

                        case "yield":
                            if (!IsInContext(ContextType.Function))
                            {
                                throw new InvalidOperationException("SyntaxError: 'yield' outside function");
                            }
                            break;

                        case "break":
                        case "continue":
                            if (!IsInContext(ContextType.Loop))
                            {
                                var msg = statementType == "break" ? "'break' outside loop" : "'continue' not properly in loop";
                                throw new InvalidOperationException($"SyntaxError: {msg}");
                            }
                            break;

                        case "await":
                            if (!IsInContext(ContextType.Async))
                            {
                                throw new InvalidOperationException("SyntaxError: 'await' outside async function");
                            }
                            break;
                    }
                }

                /// <summary>
                /// Debug method to print current context stack
                /// </summary>
                private void PrintContextStack()
                {
                    Console.WriteLine($"[CONTEXT-STACK] Current stack ({_contextStack.Count} levels):");
                    foreach (var ctx in _contextStack.Reverse())
                    {
                        Console.WriteLine($"[CONTEXT-STACK]   {ctx}");
                    }
                }

            }
        // ========================================
        // Embedded Grammar Types - from python.gram
        // These mirror Grammar.Grammar structure for PegInterpreter
        // ========================================

        public abstract class EmbeddedAtom { }

        public class EmbeddedRuleRef : EmbeddedAtom
        {
            public string Name { get; set; } = "";
            public override string ToString() => Name;
        }

        public class EmbeddedStringLiteral : EmbeddedAtom
        {
            public string Value { get; set; } = "";
            public override string ToString() => $"'{Value}'";
        }

        public class EmbeddedGroup : EmbeddedAtom
        {
            public List<EmbeddedAlternative> Alternatives { get; set; } = new();
        }

        public class EmbeddedOptional : EmbeddedAtom
        {
            public EmbeddedAtom Expression { get; set; } = null!;
        }

        public class EmbeddedZeroOrMore : EmbeddedAtom
        {
            public EmbeddedAtom Expression { get; set; } = null!;
        }

        public class EmbeddedOneOrMore : EmbeddedAtom
        {
            public EmbeddedAtom Expression { get; set; } = null!;
        }

        public class EmbeddedPositiveLookahead : EmbeddedAtom
        {
            public EmbeddedAtom Expression { get; set; } = null!;
        }

        public class EmbeddedNegativeLookahead : EmbeddedAtom
        {
            public EmbeddedAtom Expression { get; set; } = null!;
        }

        public class EmbeddedCut : EmbeddedAtom
        {
            public EmbeddedAtom Expression { get; set; } = null!;
        }

        public class EmbeddedItem
        {
            public string? Name { get; set; }
            public EmbeddedAtom Atom { get; set; } = null!;
        }

        public class EmbeddedAlternative
        {
            public List<EmbeddedItem> Items { get; set; } = new();
            public string? Action { get; set; }
        }

        public class EmbeddedRule
        {
            public string Name { get; set; } = "";
            public string? ReturnType { get; set; }
            public List<EmbeddedAlternative> Alternatives { get; set; } = new();
            public bool IsMemoized { get; set; } = false;
        }

        public class EmbeddedGrammar
        {
            public List<EmbeddedRule> Rules { get; } = new();

            public static EmbeddedGrammar GetGrammar()
            {
                var grammar = new EmbeddedGrammar();

                // Rule: file
                var rule_file = new EmbeddedRule
                {
                    Name = "file",
                    ReturnType = "mod_ty",
                    IsMemoized = false,
                    Alternatives = new()
                    {
                        new EmbeddedAlternative
                        {
                            Action = "_PyPegen_make_module(p, a)",
                            Items = new()
                            {
                                new EmbeddedItem { Name = "a", Atom = new EmbeddedOptional { Expression = new EmbeddedGroup { Alternatives = new() { new EmbeddedAlternative { Items = new() { new EmbeddedItem { Name = null, Atom = new EmbeddedRuleRef { Name = "statements" } }, } }, } } } },
                                new EmbeddedItem { Name = null, Atom = new EmbeddedRuleRef { Name = "ENDMARKER" } },
                            }
                        },
                    }
                };
                grammar.Rules.Add(rule_file);

                // Rule: interactive
                var rule_interactive = new EmbeddedRule
                {
                    Name = "interactive",
                    ReturnType = "mod_ty",
                    IsMemoized = false,
                    Alternatives = new()
                    {
                        new EmbeddedAlternative
                        {
                            Action = "_PyAST_Interactive(a, p->arena)",
                            Items = new()
                            {
                                new EmbeddedItem { Name = "a", Atom = new EmbeddedRuleRef { Name = "statement_newline" } },
